INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184001,'18087','Academia Internacional de Órgano de Granada','festival','festivales_wiki','La Academia Internacional de Órgano de Granada es un festival internacional musical dedicado al órgano y celebrado anualmente a mediados del mes de septiembre en la ciudad de Granada. Está organizado por la Real Academia de Bellas Artes de Nuestra Señora de las Angustias de Granada, y la presidencia del festival le…',NULL,NULL,'https://es.wikipedia.org/wiki/Academia_Internacional_de_Órgano_de_Granada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184002,'26089','Actual (festival)','festival','festivales_wiki','Actual es un festival de música, cine y artes que se celebra en Logroño (La Rioja, España) la primera semana de cada año, de forma ininterrumpida desde 1991 y organizado por el Gobierno de La Rioja. Es muy conocido por ser el primer festival del año en España.',NULL,NULL,'https://es.wikipedia.org/wiki/Actual_(festival)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184003,'50039','Afrikaldia','festival','festivales_wiki','Afrikaldia. Festival Vasco de Cines Africanos (AFK) es un festival de cine que se celebra en Vitoria en el mes de octubre con el fin visibilizar la diversidad y la riqueza de las culturas africanas.​ Es un festival de carácter competitivo, la primera edición fue en el año 2021​ y lo promueve la Asociación…',42.84383,-2.6710165,'https://es.wikipedia.org/wiki/Afrikaldia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184004,'90776','Aguaviva Canarias','festival','festivales_wiki','Aguaviva Canarias (originalmente, en 2005, Aguavivafest) es un festival de música que tiene lugar en Arona (Tenerife, España). Se celebra cada verano desde 2005. Organizado por el Ayuntamiento de Arona, patrocinado por el Gobierno de Canarias y el Cabildo de Tenerife, bajo la producción de La Luciérnaga…',28.099625,-16.68091,'https://es.wikipedia.org/wiki/Aguaviva_Canarias');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184005,'29001','Alcalá Suena','festival','festivales_wiki','Alcalá Suena es un festival de música celebrado en Alcalá de Henares, cuyos artistas participantes son seleccionados mediante un concurso previo. Las actuaciones son en directo, al aire libre, gratuitas, y generalmente se desarrollan el primer fin de semana de junio.',NULL,NULL,'https://es.wikipedia.org/wiki/Alcalá_Suena');
