INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184007,'04004','Almería Western Film Festival','festival','festivales_wiki','El Almería Western Film Festival (AWFF) es un festival de cine temático celebrado anualmente en el municipio español de Tabernas fundado en 2011. El festival está dedicado a la proyección y promoción del cine western, género profundamente ligado a la zona, especialmente en las décadas de los 60 y 70, por sus…',NULL,NULL,'https://es.wikipedia.org/wiki/Almería_Western_Film_Festival');
