INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184009,'04004','Almería Western Film Festival 2024','festival','festivales_wiki','La edición 14 del AWFF se celebró de los 10 al 13 de octubre de 2024 y fue dirigida por Juan Francisco Viruega.​ La gala final fue presentada por Luis Larrodera e incluyó la actuación de Vicente Navarro.​',NULL,NULL,'https://es.wikipedia.org/wiki/Almería_Western_Film_Festival_2024');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184010,'16007','Alrumbo Festival','festival','festivales_wiki','AlRumbo Festival fue un festival de música español que se celebraba en la costa gaditana desde el año 2010, atrayendo a numerosos jóvenes de toda la península ibérica. El festival fue celebrándose en diferentes localidades: Chiclana de la Frontera, Rota, Chipiona y, en la última edición organizada, preveía…',36.34152778,6.13269444,'https://es.wikipedia.org/wiki/Alrumbo_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184011,'25120','Animac','festival','festivales_wiki','Animac es un festival de cine de animación que se celebra la última semana de febrero en la localidad de Lérida y reúne las mejores producciones de animación internacional. Nació en el año 1996 con el objetivo de promocionar y dar a conocer la animación audiovisual y ser un punto de encuentro entre los…',NULL,NULL,'https://es.wikipedia.org/wiki/Animac');
