INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184014,'08007','Aplec de Calella','festival','festivales_wiki','El Aplec de Calella o Aplec Pairal de Cataluña, cuyo origen se remonta al 1926, es el decano de los encuentros de sardana, y se celebra en el Paseo Marítimo Manuel Puigvert y el Parque Dalmau de Calella como escenarios naturales.​ El encuentro nació para conmemorar el segundo aniversario de la fundación de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Aplec_de_Calella');
