INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184017,'28079','Argencine','festival','festivales_wiki','Argencine es un ciclo de cine que surge en el año 2005 a partir de la colaboración entre la Consejería de Cultura y Deporte de la Comunidad de Madrid y el Instituto Nacional de Cine y Artes Audiovisuales de Argentina. Ambas instituciones firman un acuerdo para realizar cada año un festival en Madrid y en Buenos…',NULL,NULL,'https://es.wikipedia.org/wiki/Argencine');
