INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184024,'02001','Bienal de Artes Plásticas Ciudad de Albacete','festival','festivales_wiki','La Bienal de Artes Plásticas Ciudad de Albacete, conocida también como Bienal de Albacete, es una exposición internacional de artes plásticas que se celebra cada dos años en la ciudad española de Albacete.​​​​​​',NULL,NULL,'https://es.wikipedia.org/wiki/Bienal_de_Artes_Plásticas_Ciudad_de_Albacete');
