INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184027,'29067','Brisa Festival','festival','festivales_wiki','El Brisa Festival es un festival de música que se realiza anualmente en Málaga desde el año 2021, aunque se anunció para comenzar en el 2020, tuvo que ser cancelado por el COVID-19. Cada edición celebra a finales del mes de julio, aunque según el año ha mantenido actividades en junio o agosto, con la presentación…',NULL,NULL,'https://es.wikipedia.org/wiki/Brisa_Festival');
