INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184041,'08014','Circ Cric','festival','festivales_wiki','Circ Cric es una compañía de circo española fundada en 1981 por los artistas de circo Montserrat Trias y Tortell Poltrona.​​​ En 2005 recibió el Premio Nacional del Circo de Cataluña.​',NULL,NULL,'https://es.wikipedia.org/wiki/Circ_Cric');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184042,'41091','Circada','festival','festivales_wiki','El Festival Circada, también conocido como CIRCADA o Festival de Circo de Sevilla, es un festival de circo contemporáneo español que se celebra anualmente en Sevilla, durante el mes de junio, desde 2008.',NULL,NULL,'https://es.wikipedia.org/wiki/Circada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184043,'08003','Circuit Festival','festival','festivales_wiki','Circuit Festival —también conocido como Circuit Festival Barcelona— es un festival internacional de gays y lesbianas que se celebra anualmente en Barcelona desde 2008. Es el mayor festival de ocio de estas características que se celebra en Europa cada año.​ En la edición de 2012 la asistencia fue de 70 000 personas…',NULL,NULL,'https://es.wikipedia.org/wiki/Circuit_Festival');
