INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184045,'43148','Concurso Internacional de Castillos de Fuegos Artificiales de Tarragona','festival','festivales_wiki','El Concurso Internacional de Castillos de Fuegos Artificiales Ciudad de Tarragona fue creado el año 1990, en una ciudad con una larga tradición pirotécnica. Tarragona ya contaba con fabricación de "voladores de fuego griego" por parte de los drogueros y los especieros en el año 1383, y se usaban para las fiestas…',NULL,NULL,'https://es.wikipedia.org/wiki/Concurso_Internacional_de_Castillos_de_Fuegos_Artificiales_de_Tarragona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184046,'14021','Concurso Nacional de Arte Flamenco','festival','festivales_wiki','El Concurso Nacional de Arte Flamenco de Córdoba es un certamen de carácter trianual que se celebra en la ciudad de Córdoba (España) desde 1956, con el deseo de rescatar el cante con la pureza tradicional del “viejo Cante Jondo” (que se mantenía al margen de los circuitos de espectáculos) y con el deseo, al mismo…',NULL,NULL,'https://es.wikipedia.org/wiki/Concurso_Nacional_de_Arte_Flamenco');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184047,'06001','Contempopránea','festival','festivales_wiki','Contempopránea es un festival de música pop independiente que se celebra todos los veranos en Alburquerque (Badajoz). En él se reúnen año tras año numerosos artistas de la escena indie española, y millares de seguidores. A partir de 2014, la edición se ha dividido entre esta localidad pacense y Badajoz.​ El…',NULL,NULL,'https://es.wikipedia.org/wiki/Contempopránea');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184048,'12028','Costa de Fuego','festival','festivales_wiki','Costa de Fuego fue un festival dedicado al rock más contundente y a los diversos estilos del metal que se celebró en la ciudad costera mediterránea de Benicasim, en la provincia de Castellón, España, los días 20 y 21 de julio de 2012.',NULL,NULL,'https://es.wikipedia.org/wiki/Costa_de_Fuego');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184049,'20069','Crai Nou','festival','festivales_wiki','Crai Nou es la ópera prima de la directora de cine rumana Alina Grigore; fue galardonada con la Concha de Oro de la mejor película en la 69.º Festival Internacional de Cine de San Sebastián.​ Versa sobre la violencia familiar​ y el jurado del certamen vasco reconoció en ella su "compromiso con el lenguaje…',NULL,NULL,'https://es.wikipedia.org/wiki/Crai_Nou');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184050,'08003','D''A Film Festival','festival','festivales_wiki','El D''A Film Festival ​ es un festival de cine de autor que se celebra anualmente en Barcelona. El festival está dirigido por Carlos R. Ríos.',NULL,NULL,'https://es.wikipedia.org/wiki/D''A_Film_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184051,'28079','Dcode Festival','festival','festivales_wiki','El Dcode Festival o Dcode es un festival de música que se celebra el mes de septiembre en el recinto deportivo de Cantarranas, perteneciente al Campus de la Universidad Complutense de Madrid. La primera edición del festival fue celebrada en el año 2011 y tuvo una duración de dos días. Desde la edición de 2013, la…',NULL,NULL,'https://es.wikipedia.org/wiki/Dcode_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184052,'05243','Demandafolk','festival','festivales_wiki','Demandafolk fue un festival de música tradicional gratuito que se celebró anualmente en Tolbaños de Arriba, en la comarca de la Sierra de la Demanda, Burgos. Se autoproclamaba un festival no convencional ya que, con un cartel compuesto por importantes grupos del panorama de música tradicional español, la…',NULL,NULL,'https://es.wikipedia.org/wiki/Demandafolk');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184053,'32054','Derrame Rock','festival','festivales_wiki','El Festival Derrame Rock es un festival de música rock creado en 1996 que se celebra en Asturias , España. Su principal organizador es el sello discográfico Santo Grial Producciones. En 2011 el festival fue celebrado en Orense con gran afluencia de público, el doble que en las ediciones celebradas en el Principado…',NULL,NULL,'https://es.wikipedia.org/wiki/Derrame_Rock');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184054,'20069','Diego Galán','festival','festivales_wiki','Diego Galán Fernández (Tánger, 13 de octubre de 1946-Madrid, 15 de abril de 2019)​ fue un escritor, articulista, crítico cinematográfico y cineasta. Dirigió el Festival Internacional de Cine de San Sebastián entre 1986 y 1989 y entre 1995 y 2000.',NULL,NULL,'https://es.wikipedia.org/wiki/Diego_Galán');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184055,'29001','Don Juan en Alcalá','festival','festivales_wiki','Don Juan en Alcalá es la representación teatral del Don Juan Tenorio, según la obra de José Zorrilla, celebrada en Alcalá de Henares. Se interpreta anualmente, desde 1984, en el fin de semana más cercano al día uno de noviembre de cada año.',NULL,NULL,'https://es.wikipedia.org/wiki/Don_Juan_en_Alcalá');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184056,'04004','Dreambeach Festival','festival','festivales_wiki','Dreambeach Festival es un festival de música electrónica que se celebra anualmente en Andalucía, anteriormente en la provincia de Almería y desde 2026 en la provincia de Málaga.',NULL,NULL,'https://es.wikipedia.org/wiki/Dreambeach_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184057,'04004','El cuento de la vida','festival','festivales_wiki','El cuento de la vida es un cortometraje español de 2014 rodado en Almería.',NULL,NULL,'https://es.wikipedia.org/wiki/El_cuento_de_la_vida');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184058,'28065','Electric Weekend','festival','festivales_wiki','El Electric Weekend, también conocido como Getafe Electric Festival, fue un festival de rock que se celebró en 2008 en el auditorio John Lennon situado en Getafe, Madrid, España. Fue organizado por la promotora de conciertos Last Tour International.',NULL,NULL,'https://es.wikipedia.org/wiki/Electric_Weekend');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184059,'09003','Electrosonic Festival','festival','festivales_wiki','Electrosonic Festival fue un festival de música, arte y pensamiento electrónico que se celebró en Burgos (España). Tuvo cinco ediciones, desde 2005 a 2009. En sus cinco ediciones, el festival llegó a alcanzar los 25 000 asistentes.',42.3408,-3.6997,'https://es.wikipedia.org/wiki/Electrosonic_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184060,'08003','Elrow','festival','festivales_wiki','Elrow (estilizado elrow) es una empresa española, organizadora de eventos de música electrónica, especialmente house y techno. Su sede central se encuentra en Bilbao, y cuenta con delegaciones en Barcelona e Ibiza. Según la propia empresa, hasta 2019 llevaron a cabo más de 150 eventos, en 67 ciudades de 35 países…',NULL,NULL,'https://es.wikipedia.org/wiki/Elrow');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184061,'06018','Emérita Lúdica','festival','festivales_wiki','Emerita Lvdica es un festival de recreación histórica sobre el mundo romano celebrado anualmente en el mes de mayo en la ciudad de Mérida (España). Fue declarada fiesta de Interés Turístico Regional de Extremadura en 2022 y en la edición de 2024 contó con más de 130 000 visitantes. La XV edición del festival se…',NULL,NULL,'https://es.wikipedia.org/wiki/Emérita_Lúdica');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184062,'42173','Enclave de Agua','festival','festivales_wiki','El Enclave de Agua Afroamerican Music Festival es un festival de música afroamericana. Se celebra en las Márgenes del Duero, en la ciudad de Soria cada verano desde el año 2008. Tiene lugar el último fin de semana del mes de julio.',NULL,NULL,'https://es.wikipedia.org/wiki/Enclave_de_Agua');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184063,'11031','Encuentro de Coros Parroquiales Almas Jóvenes','festival','festivales_wiki','Bajo el nombre de Encuentro de Coros Parroquiales Almas Jóvenes se celebra en la ciudad de Cádiz (España) un certamen-festival de coros vinculados a distintas parroquias católicas de la provincia gaditana. El encuentro ha contado durante sus once ediciones con la colaboración de varios coros procedentes de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Encuentro_de_Coros_Parroquiales_Almas_Jóvenes');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184064,'29067','Espeto Dark Festival','festival','festivales_wiki','El Espeto Dark Festival es un festival de música alternativa. Se celebra cada año en Málaga, España alrededor de la segunda mitad de diciembre coincidiendo con el Solsticio de diciembre.',NULL,NULL,'https://es.wikipedia.org/wiki/Espeto_Dark_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184065,'29069','Euro Film Festival','festival','festivales_wiki','El Euro Film Festival, oficialmente Festival de Cine Europeo, es un certamen cinematográfico celebrado anualmente en Marbella, España. El evento es patrocinado por el Ayuntamiento de Marbella​ y su primera edición se llevó a cabo entre el 23 y el 26 de noviembre del 2011.',NULL,NULL,'https://es.wikipedia.org/wiki/Euro_Film_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184066,'33024','EuroYeyé','festival','festivales_wiki','El Euroyeyé es un festival mod de música que se celebra en Gijón habitualmente en el último fin de semana de julio de cada año, en el que además de actuaciones musicales, hay otras actividades, como la Scootercruzada o un ciclo de cine de culto de los años 60, además de diversas exposiciones de arte y fotografía.',NULL,NULL,'https://es.wikipedia.org/wiki/EuroYeyé');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184067,'08102','European Balloon Festival','festival','festivales_wiki','El European Balloon Festival es la concentración de globos aerostáticos más importante de España​ y del sur de Europa,​ y se celebra en Igualada, (Barcelona) España, cada año en el mes de julio desde su creación en el año 1997.​ Los impulsores de la iniciativa fueron el entonces concejal de promoción del…',41.584543,1.630865,'https://es.wikipedia.org/wiki/European_Balloon_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184068,'03064','Experimentaclub','festival','festivales_wiki','Experimentaclub fue un festival de música electrónica y música experimental que se realizó anualmente en Madrid desde el año 2000 (exceptuando el año 2001) hasta 2010. El festival fue idea del músico riojano Javier Colis y estuvo codirigido en sus dos primeras ediciones con sus ex-compañeros en el grupo Mil Dolores…',NULL,NULL,'https://es.wikipedia.org/wiki/Experimentaclub');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184069,'06049','FETEN','festival','festivales_wiki','FETEN es una feria europea de artes escénicas para el sector infantil y familiar que se celebra en Gijón (Asturias, España) desde 1991. La organiza la Fundación Municipal de Cultura del Ayuntamiento de Gijón.​​​​ Tiene como objetivo ofrecer un punto de encuentro a los profesionales de las artes escénicas que…',NULL,NULL,'https://es.wikipedia.org/wiki/FETEN');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184070,'08003','FICMA','festival','festivales_wiki','El SUNCINE Festival Internacional de Cine del Medio Ambiente (conocido por sus siglas FICMA) fue fundado en 1993 y se celebra anualmente en Barcelona y México, siendo un punto de encuentro de la industria cinematográfica, activistas ambientales y ciudadanía. Fundado en 1993 por el director y productor de cine…',NULL,NULL,'https://es.wikipedia.org/wiki/FICMA');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184071,'46250','Fallas de Valencia','festival','festivales_wiki','Las Fallas de Valencia (Falles en valenciano) son unas fiestas que se celebran del 1 al 19 de marzo y que suponen una arraigada tradición en la ciudad española de Valencia. Oficialmente empiezan el último domingo de febrero con el acto de la crida (en valenciano; ''pregón o llamada'', en español). Actualmente, esta…',39.47,-0.3764,'https://es.wikipedia.org/wiki/Fallas_de_Valencia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184072,'20069','Feministaldia','festival','festivales_wiki','Feministaldia es un Festival de Cultura Feminista organizado desde 2006 en San Sebastián por la plataforma política Plazandreok.',NULL,NULL,'https://es.wikipedia.org/wiki/Feministaldia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184073,'08113','Feria Mediterránea de Manresa','festival','festivales_wiki','La Fira Mediterrània de Manresa es un mercado de propuestas artísticas que utilizan la raíz, la tradición y la cultura popular como motor creativo. Se celebra anualmente desde el año 1998 y se ha convertido en un marco de intercambios entre profesionales del sector que venden y compran espectáculos. La mayoría de…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_Mediterránea_de_Manresa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184074,'08194','Feria de Abril de Cataluña','festival','festivales_wiki','La Feria de Abril de Cataluña (en catalán y oficialmente: Fira d''Abril de Catalunya)​ es una fiesta popular de tradición andaluza que se celebra en Barcelona anualmente, durante 10 días entre abril y mayo, en un recinto ferial del área metropolitana de la ciudad, donde se instalan numerosas casetas y atracciones.…',41.40657416,2.22225103,'https://es.wikipedia.org/wiki/Feria_de_Abril_de_Cataluña');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184075,'06049','Feria de Artes Escénicas de Castilla-La Mancha','festival','festivales_wiki','La Feria de Artes Escénicas de Castilla-La Mancha es un evento cultural de carácter internacional que tiene lugar anualmente en la ciudad española de Albacete.​​​​​ Su primera edición se celebró en 1997 y constituye el foro más importante dedicado a la escena contemporánea de Castilla-La Mancha.',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_Artes_Escénicas_de_Castilla-La_Mancha');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184076,'20069','Feria de Artes Escénicas de San Sebastián (dFERIA)','festival','festivales_wiki','La Feria de Artes Escénicas de San Sebastián (dFERIA) es una Feria de artes escénicas desarrollada en el municipio de San Sebastián del País Vasco (España).​ Comenzó su andadura en 1988 impulsada por el Ayuntamiento de San Sebastián. La Feria se desarrolla anualmente, habitualmente en marzo, y se convierte durante…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_Artes_Escénicas_de_San_Sebastián_(dFERIA)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184077,'06049','Feria de Circo Trapezi','festival','festivales_wiki','La Feria de Circo Trapezi (en catalán, Trapezi, Fira del Circ de Catalunya), también conocido como Trapezi y desde 2011 Trapezi Reus, es un festival español dedicado al circo contemporáneo que se celebra desde 1997, cada año, en el mes de mayo, en Reus.​ Es considerada la primera feria de circo contemporáneo de…',NULL,NULL,'https://es.wikipedia.org/wiki/Feria_de_Circo_Trapezi');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184078,'25244','Feria de Tárrega','festival','festivales_wiki','FiraTàrrega, antes Fira de Teatre al Carrer de Tàrrega o Fira del Teatre de Tàrrega (Feria del Teatro de Tárrega), es el mercado internacional de las artes escénicas más importante y con más trayectoria de España y uno de los más relevantes de Europa. Tiene lugar cada año durante el segundo fin de semana del mes de…',41.64638889,1.13944444,'https://es.wikipedia.org/wiki/Feria_de_Tárrega');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184079,'02001','FesTVal','festival','festivales_wiki','El FesTVal es el Festival Nacional de Televisión de España. Es el primer festival que se dedica exclusivamente a la televisión en todos sus formatos: programas, concursos, magazines, series, entre otro formatos. Tiene su sede en la ciudad española de Vitoria y en su edición de primavera hasta el momento ha tenido…',NULL,NULL,'https://es.wikipedia.org/wiki/FesTVal');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184080,'12029','Feslloc','festival','festivales_wiki','Feslloc, anteriormente escrito Feslloch, es un festival de música en valenciano organizado por la Asociació Cultural Feslloc, formada por Escola Valenciana y el Ayuntamiento de Benlloc, que se celebra el segundo fin de semana de julio de cada año en la localidad valenciana de Benlloc (Plana Alta) desde 2007.​…',40.2106,0.0269,'https://es.wikipedia.org/wiki/Feslloc');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184081,'28079','Festimad','festival','festivales_wiki','Festimad fue un festival cultural de música alternativa que se celebró anualmente en la Comunidad de Madrid, España, desde 1994, generalmente el último fin de semana de mayo. Festimad incluía varios festivales culturales paralelos, tales como Performa, Graffiti, Universimad o Cinemad, aunque su relevancia se debía…',NULL,NULL,'https://es.wikipedia.org/wiki/Festimad');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184082,'08200','Festival Altaveu','festival','festivales_wiki','El Festival Altaveu, también conocido como el Festival de la Música i la Cançó de Sant Boi de Llobregat, es un festival de música que se celebra anualmente el mes de septiembre en San Baudilio de Llobregat desde 1989. En 2021 celebra su trigésimo segunda edición. Actualmente, a nivel estilístico, es un festival de…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Altaveu');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184083,'50297','Festival Amante','festival','festivales_wiki','El festival Amante es un festival de música indie, pop, rock, que se celebra en la localidad de Borja (provincia de Zaragoza, España) durante el mes de agosto.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Amante');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184084,'50297','Festival Aragón Negro','festival','festivales_wiki','El Festival Aragón Negro, conocido popularmente como Aragón Negro es un festival literario nacido en el año 2014 gracias a la iniciativa del escritor y periodista Juan Bolea. Este evento se celebra en toda la Comunidad de Aragón (España) y está organizado por Fundación Caja Rural de Aragón de Bantierra y…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Aragón_Negro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184085,'50297','Festival Asalto','festival','festivales_wiki','El Festival Asalto es un evento anual de arte urbano que se celebra en Zaragoza desde el año 2005.​ Acoge obras de artistas de relevancia internacional como Boa Mistura​ o Tavar Zawacki.​',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Asalto');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184086,'08003','Festival Aéreo de Barcelona','festival','festivales_wiki','El Festival Aéreo de Barcelona, conocido como Festa al Cel («Fiesta en el Cielo» en catalán), es un festival aéreo que se celebra anualmente en el mes de septiembre en las playas de Barcelona, España. con motivo de las Fiestas de la Mercè. En el año 2013 el festival no se pudo celebrar en Barcelona, pero se…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Aéreo_de_Barcelona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184087,'16009','Festival Aéreo de Cádiz','festival','festivales_wiki','El Festival Aéreo de Cádiz es un evento anual, actualmente sin asignación presupuestaria, organizado por Ayuntamiento de Cádiz en colaboración con el Ejército del Aire y la Armada de España,​ que celebra la ciudad antes citada en el mes de septiembre desde 2008.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Aéreo_de_Cádiz');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184088,'33024','Festival Aéreo de Gijón','festival','festivales_wiki','El Festival Aéreo de Gijón es un festival aéreo que se celebra anualmente en el mes de julio en la Playa de San Lorenzo de Gijón (España). Desde 2022 queda englobado dentro de la denominada Fiesta del Cielo,​ un festival de una semana de duración con distintas actividades, cuyo acto central es el Festival Aéreo.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Aéreo_de_Gijón');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184089,'29067','Festival Aéreo de Málaga','festival','festivales_wiki','El Festival Aéreo de Málaga (FAM) es un festival aéreo que se celebra anualmente en el mes de septiembre en la Playa de la Malagueta, en Málaga (España).',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Aéreo_de_Málaga');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184090,'36015','Festival Aéreo de Vigo','festival','festivales_wiki','El Festival Aéreo de Vigo (FAV) fue un festival aéreo que se celebraba anualmente entre 2004 y 2012​ en la Playa de Samil, en la ciudad gallega de Vigo, España.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Aéreo_de_Vigo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184091,'08003','Festival Blues de Barcelona','festival','festivales_wiki','El Festival Blues de Barcelona es un festival de blues que se celebra en la ciudad condal desde 2003, organizado por la asociación Capibola.​ La primera edición se llamaba Festival de Blues de Nou Barris, aunque en ediciones posteriores adoptó el nombre actual.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Blues_de_Barcelona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184092,'06018','Festival Bollywood de Extremadura Beneshwar','festival','festivales_wiki','El Festival Bollywood de Extremadura Beneshwar, también conocido simplemente como Beneshwar, es un festival artístico y cultural que se celebra anualmente, a finales de abril o principios de mayo, en la ciudad de Mérida (España) . El festival está dedicado a las artes escénicas de la India, especialmente a la danza…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Bollywood_de_Extremadura_Beneshwar');
