INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184094,'45168','Festival CiBRA','festival','festivales_wiki','El Festival del Cine y la Palabra (CiBRA), es una muestra cinematográfica y literaria celebrada anualmente en Toledo, España. Basado en cine y literatura, como su nombre indica, se proyectan películas basadas en guiones adaptados a una obra, cuyo soporte anterior haya sido una novela, ensayo, teatro, o gráfico como…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_CiBRA');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184095,'21042','Festival Coral del Atlántico','festival','festivales_wiki','El Festival Coral del Atlántico es un evento cultural celebrado en Isla Cristina, en el suroeste español, de forma anual tras las celebraciones patronales del Rosario, día 7 de octubre, patrona de la ciudad. La sede del festival es la iglesia de Nuestra Señora de los Dolores.​ Fue fundado en 1987 por el músico y…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Coral_del_Atlántico');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184096,'08003','Festival Cruïlla Barcelona','festival','festivales_wiki','El Festival Cruïlla es un festival de música que se celebra en el mes de julio en Barcelona. Ofrece un cóctel de estilos, culturas y sensaciones que traen artistas de todas las tallas y sensibilidades, liberando su energía sobre los escenarios. La edición del 2020 del Festival Cruïlla se celebró los días 2, 3, 4 de…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Cruïlla_Barcelona');
