INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184098,'40205','Festival El Cencerro','festival','festivales_wiki','El Cencerro Rural Ad Festival es un festival no lucrativo de publicidad rural​​​​ que se celebra en Losana de Pirón, pedanía del municipio de Torreiglesias en la provincia de Segovia. El festival nace con la intención de dar cabida a aquellas creaciones publicitarias que hagan alusión a productos agrícolas o…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_El_Cencerro');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184099,'28065','Festival En Vivo','festival','festivales_wiki','El Festival En Vivo (también conocido como En Vivo Festival o simplemente En Vivo) es un festival de música, organizado por la promotora musical Last Tour, que se celebra actualmente en Pamplona (Navarra). Se trata de un festival compuesto principalmente por artistas nacionales Su primera edición tuvo lugar durante…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_En_Vivo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184100,'28079','Festival Erótico de Madrid','festival','festivales_wiki','El Festival Erótico de Madrid o Exposex fue un festival internacional dedicado al cine pornográfico que desde el año 2005 se celebró anualmente en Madrid, España. En 2006 fue amadrinado por la actriz pornográfica Celia Blanco y la edición 2007 fue la última en que se mantuvo en activo, ya que el evento fue…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Erótico_de_Madrid');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184101,'37354','Festival Europeo de Cortometrajes Villamayor de Cine','festival','festivales_wiki','El Festival Europeo de Cortometrajes Europeos Villamayor de Cine! es un evento cinematográfico anual que se celebra cada mes de agosto en la localidad de Villamayor de Santiago (Cuenca). Este festival cinematográfico de ámbito europeo nacido en 2008 tiene como principales objetivos impulsar la categoría de los…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Europeo_de_Cortometrajes_Villamayor_de_Cine');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184102,'06006','Festival Flamenco Mártir Santa Eulalia','festival','festivales_wiki','El Festival Flamenco Mártir Santa Eulalia fue un festival de música flamenca celebrado en Mérida (España) desde 1989 hasta 2010. Durante sus veinte ediciones reunió a cantaores, guitarristas y bailarines provenientes principalmente de las provincias de Badajoz, Sevilla y Murcia, así como de otras zonas de Andalucía.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Flamenco_Mártir_Santa_Eulalia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184103,'04004','Festival Flamenco de Almería','festival','festivales_wiki','El festival flamenco de Almería es un acontecimiento musical que se celebra en la ciudad de Almería (Andalucía, España) desde el año 1966 dedicado por entero al flamenco.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Flamenco_de_Almería');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184104,'05002','Festival Folklorico Internacional de Musica y Danza Popular de Aviles','festival','festivales_wiki','El Festival Folklórico Internacional de Música y Danza Popular de Avilés es un evento cultural que se celebra anualmente en la ciudad de Avilés (Asturias, España), habitualmente durante el mes de agosto y en el marco de las fiestas de San Agustín. Organizado por la Agrupación Folklórica Sabugo ¡Tente Firme!, tiene…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Folklorico_Internacional_de_Musica_y_Danza_Popular_de_Aviles');
