INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184106,'08003','Festival Griego','festival','festivales_wiki','El Festival Griego​​ (en catalán, Grec) es un festival internacional de teatro, danza, música y circo, celebrado en Barcelona, España. Con una larga tradición en la vida cultural de la ciudad, durante su historia, no solo se ha convertido en la principal atracción del verano barcelonés, sino también en una…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Griego');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184107,'25061','Festival Horror Online Art de Navarra','festival','festivales_wiki','El Festival Internacional de Cine Fantástico y de Terror de Navarra Horror Online Art es una muestra cinematográfica creada en 2012 que se realiza anualmente en la Comunidad Foral de Navarra. El festival se divide en dos partes. En primer lugar, se lleva a cabo una edición en línea a competición, donde participan…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Horror_Online_Art_de_Navarra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184108,'18127','Festival Hot Point','festival','festivales_wiki','El Festival Hot Point es un festival de música rap celebrado a principio de junio en Maracena, Granada desde el año 2005. Por él han pasado artistas reconocidos como Nach, Tote King, Falsalarma, SFDK, R de Rumba, entre varios otros. Fue cancelado después de su tercera edición.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Hot_Point');
