INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184112,'29067','Festival Intercultural Ciudad de Málaga','festival','festivales_wiki','El Festival Intercultural Ciudad de Málaga se celebró en primavera de 2009 en la Plaza de la Marina de esta ciudad del sur de España. Este festival consiste en una muestra de gastronomía, música, danza y artesanía que pretende presentar la diversidad internacional. Con ella colaboran asociaciones y colectivos de…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Intercultural_Ciudad_de_Málaga');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184113,'05002','Festival Intercéltico de Avilés y Comarca','festival','festivales_wiki','El Festival Intercéltico de Avilés y Comarca (en asturiano y oficialmente, Festival Intercélticu d''Avilés y Comarca) es un festival que se celebra durante verano en Avilés y su comarca (Asturias, España) desde el año 1997.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Intercéltico_de_Avilés_y_Comarca');
