INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184122,'08113','Festival Internacional de Cine Negro de Manresa','festival','festivales_wiki','El Fecinema (Festival Internacional de Cinema Negre de Manresa, Festival Internacional de Cine Negro de Manresa) es un festival cinematográfico que se celebra anualmente en la ciudad barcelonesa de Manresa (España). Su primera edición tuvo lugar en 1999 y premia fundamentalmente cortometrajes de cine negro, al…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Cine_Negro_de_Manresa');
