INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184124,'04004','Festival Internacional de Cine de Almería','festival','festivales_wiki','El Festival Internacional de Cine de Almería, abreviado FICAL, es un certamen cinematográfico que se desarrolla anualmente en la ciudad de Almería a mediados del mes de noviembre organizado por la Diputación Provincial de Almería.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Cine_de_Almería');
