INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184127,'22125','Festival Internacional de Cine de Huesca','festival','festivales_wiki','El Festival Internacional de Cine de Huesca es un certamen cinematográfico que se celebra anualmente en la ciudad española de Huesca. Fue creado por la Peña Recreativa Zoiti en abril de 1973 con el nombre de Certamen Internacional de Films Cortos Ciudad de Huesca. En 1989 cambió su denominación a Festival de Cine…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Cine_de_Huesca');
