INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184130,'28079','Festival Internacional de Cine de Madrid','festival','festivales_wiki','El Festival Internacional de Cine de Madrid es un festival anual cinematográfico español centrado en cine independiente. Fue fundado en 1997 en Madrid. Las galas tienen lugar en el mes de julio.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Cine_de_Madrid');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184131,'29069','Festival Internacional de Cine de Marbella','festival','festivales_wiki','El Festival Internacional de Cine de Marbella (en inglés, Marbella International Film Festival), es un festival de cine celebrado anualmente desde 2006 en la ciudad malagueña de Marbella (España). Es el proyecto bandera la organización benéfica británica New World Trust y está dedicado al cine independiente de…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Cine_de_Marbella');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184132,'02001','Festival Internacional de Circo de Albacete','festival','festivales_wiki','El Festival Internacional de Circo de Albacete (en inglés: Albacete International Circus Festival) es un festival dedicado al mundo de las artes circenses que tiene lugar anualmente en la ciudad española de Albacete desde 2008; desde 2012 tiene lugar en el Teatro Circo de Albacete. Los principales premios que en él…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Circo_de_Albacete');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184133,'28079','Festival Internacional de Cortometrajes La Boca del Lobo','festival','festivales_wiki','El Festival Internacional La Boca del Lobo es un festival de cine, categoría cortometrajes que se celebra durante las últimas semanas de octubre en Madrid, España. Comienza su andadura como iniciativa privada en octubre de 1998 en un momento en que no son muy prolíficos los festivales de cortometrajes. Ese mismo…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Cortometrajes_La_Boca_del_Lobo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184134,'29025','Festival Internacional de Cortometrajes y Cine Alternativo de Benalmádena','festival','festivales_wiki','El Festival Internacional de Cortometrajes y Cine Alternativo de Benalmádena (FICCAB) es un festival de cine celebrado anualmente desde 1998 en la localidad malagueña de Benalmádena (España), dedicado, como su nombre indica, al cine alternativo y en especial al corto. El festival se desarrolla entre los mes de…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Cortometrajes_y_Cine_Alternativo_de_Benalmádena');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184135,'43148','Festival Internacional de Dixieland de Tarragona','festival','festivales_wiki','El Festival Internacional de Dixieland de Tarragona, que se celebra la semana anterior a la de Pascua y acoge un centenar de actividades y conciertos, 25 formaciones y 175 músicos, nace en 1994 en Tarragona, una ciudad donde desde la restauración de los ayuntamientos democráticos, el jazz se había recuperado como…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Dixieland_de_Tarragona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184136,'04004','Festival Internacional de Jazz de Almería','festival','festivales_wiki','Desde 1985 se celebra un festival anual (con algunos años de excepción) de jazz en la ciudad de Almería (Andalucía, España). Han participado en el mismo músicos del prestigio de Chick Corea o Pedro Iturralde.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Jazz_de_Almería');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184137,'08003','Festival Internacional de Jazz de Barcelona','festival','festivales_wiki','El Festival Internacional de Jazz de Barcelona (actualmente Voll-Damm Festival Internacional de Jazz de Barcelona), fundado en 1966 por el empresario Joan Roselló, es uno de los festivales con más solera de España.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Jazz_de_Barcelona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184138,'18087','Festival Internacional de Jazz de Granada','festival','festivales_wiki','El Festival Internacional de Jazz de Granada se celebra en dicha ciudad de Andalucía (España) , desde el año 1980, durante el mes de noviembre, actualmente organizado por una Oficina de carácter público.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Jazz_de_Granada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184139,'28079','Festival Internacional de Jazz de Madrid','festival','festivales_wiki','Desde los años 80 el jazz ocupa un lugar preferente en la programación musical de Madrid. Prácticamente todas las salas de música en directo programan jazz durante todo el año. En sus locales es fácil encontrar a grandes figuras internacionales junto a figuras emergentes, a formaciones de jóvenes músicos que…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Jazz_de_Madrid');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184140,'18087','Festival Internacional de Jóvenes Realizadores de Granada','festival','festivales_wiki','El Festival Internacional de Jóvenes Realizadores de Granada es un acontecimiento cultural dedicado al cine de autor celebrado anualmente a mediados de abril en la ciudad de Granada. El festival, que congrega a directores de todo el mundo, incluye entre sus actividades un Certamen de cortometrajes.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Jóvenes_Realizadores_de_Granada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184141,'28079','Festival Internacional de Magia de Madrid','festival','festivales_wiki','El Festival Internacional de Magia de Madrid es un festival español dedicado al arte de la magia y el ilusionismo, que se celebra anualmente, desde 2011, en el Circo Price de Madrid, bajo la dirección de Jorge Blass.​​​ Está considerado un referente internacional para los magos de los diferentes países del mundo.​​​',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Magia_de_Madrid');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184142,'49275','Festival Internacional de Música "Pórtico de Zamora"','festival','festivales_wiki','El Festival Internacional de Música "Pórtico de Zamora" es un congreso en formato de festival de música clásica antigua, que se celebra cada año en el mes de marzo desde 2003 en Zamora (España), dos semanas antes de la Semana Santa.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Música_"Pórtico_de_Zamora"');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184143,'08307','Festival Internacional de Música Popular Tradicional de Villanueva y Geltrú','festival','festivales_wiki','El Festival Internacional de Música Popular Tradicional se celebra en Villanueva y Geltrú, Cataluña, desde el año 1981. Es, por tanto, el certamen más antiguo de España de músicas del mundo, étnicas o de raíz. Se celebra durante tres jornadas en el mes de julio con una periodicidad anual.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Música_Popular_Tradicional_de_Villanueva_y_Geltrú');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184144,'35016','Festival Internacional de Música de Canarias','festival','festivales_wiki','El Festival Internacional de Música de Canarias es un festival de música clásica, que se celebra cada año en los meses de enero y febrero desde 1985 en Las Palmas de Gran Canaria y Santa Cruz de Tenerife.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Música_de_Canarias');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184145,'38012','Festival Internacional de Música de Cine de Tenerife','festival','festivales_wiki','El Festival Internacional de Música de Cine de Tenerife, también conocido como FIMUCITÉ, es un festival desarrollado en Santa Cruz de Tenerife (Tenerife, Canarias, España) creado en 2007 por el compositor y director de orquesta Diego Navarro y la producción ejecutiva de Ana Molowny. Se trata de un encuentro anual…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Música_de_Cine_de_Tenerife');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184146,'21042','Festival Internacional de Música de Cámara de Isla Cristina','festival','festivales_wiki','El Festival Internacional de Música de Isla Cristina (FIMIC) es un festival de una semana de duración, celebrado en agosto en Isla Cristina, Andalucía, España, centrado en la música de cámara. En el FIMIC, aparte de los conciertos, también se llevan a cabo otras actividades artísticas como exposiciones, muestras,…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Música_de_Cámara_de_Isla_Cristina');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184147,'07026','Festival Internacional de Música de Ibiza','festival','festivales_wiki','El Festival Internacional de Música de Ibiza es un festival de música clásica, que se celebra cada dos años en el mes de agosto desde 1987 en el pueblo de San Carlos de Peralta, Santa Eulalia del Río, Ibiza. Cuenta con dos sedes, que son el Centro Cultural de San Carlos y la Iglesia de San Carlos (conciertos de…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Música_de_Ibiza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184148,'11021','Festival Internacional de Música de Jimena de la Frontera','festival','festivales_wiki','El Festival Internacional de Música de Jimena de la Frontera fue un evento cultural de renombre que se celebraba anualmente en Jimena de la Frontera, Cádiz, España. Desde su primera edición en el año 2000, el festival ofreció una programación ecléctica que abarcaba géneros como música clásica, jazz, flamenco y…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Música_de_Jimena_de_la_Frontera');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184149,'11032','Festival Internacional de Música de Sanlúcar de Barrameda','festival','festivales_wiki','El Festival Internacional de Música de Sanlúcar de Barrameda, denominado "A orillas del Guadalquivir" se celebra anualmente en la ciudad española de Sanlúcar de Barrameda, en Andalucía, en el mes de agosto. Se creó en los años 1980 bajo el impulso de Juan Rodríguez Romero, músico sanluqueño que sigue siendo el…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Música_de_Sanlúcar_de_Barrameda');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184150,'04004','Festival Internacional de Música de Tecla Española','festival','festivales_wiki','El Festival Internacional de Música de Tecla Española (FIMTE), también conocido por su traducción al inglés, International Festival of Spanish Keyboard Music, es un festival con sede en Almería, España, dedicado a organizar conciertos y actos académicos en torno al clave y el pianoforte. Fue fundado en 2000​ para…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Música_de_Tecla_Española');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184151,'08023','Festival Internacional de Patchwork Sitges','festival','festivales_wiki','Todos los años en la población de Sitges tiene lugar el Festival Internacional de Patchwork . Se celebra en el centro del pueblo y todos los aficionados del sector del arte textil pueden acercarse a él. El festival suele celebrarse en marzo y cuenta con más de 100 expositores en el interior de la feria comercial.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Patchwork_Sitges');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184152,'18087','Festival Internacional de Poesía Ciudad de Granada','festival','festivales_wiki','El Festival Internacional de Poesía Ciudad de Granada o FIPCG es un evento cultural dedicado a la poesía celebrado anualmente en la ciudad de Granada, a mediados de mayo. En el festival participan los mejores autores del panorama literario internacional, y se desarrolla en el Centro Federico García Lorca y otros…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Poesía_Ciudad_de_Granada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184153,'39075','Festival Internacional de Santander','festival','festivales_wiki','El Festival Internacional de Santander (FIS) es un festival de música que se celebra todos los años en la ciudad de Santander y la comunidad autónoma de Cantabria (España), desde mediados del siglo XX.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Santander');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184154,'18087','Festival Internacional de Tango de Granada','festival','festivales_wiki','Festival Internacional de Tango de Granada es un evento cultural dedicado al tango celebrado en la ciudad de Granada y organizado por el ayuntamiento, a finales de marzo y principios de abril. Se trata de uno de los festivales pioneros y más importantes de Europa dedicado a este baile. Fundado en 1988, por él han…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Tango_de_Granada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184155,'11020','Festival Internacional de Tango de Jerez','festival','festivales_wiki','El Festival Internacional de Tango de Jerez es un festival de danza y música relativo al tango que anualmente se celebra en la ciudad de Jerez de la Frontera (Andalucía, España). Se fundó en 2006 y, consolidado, sigue en la actualidad.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Tango_de_Jerez');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184156,'43148','Festival Internacional de Tango de Tarragona','festival','festivales_wiki','El Festival Internacional de Tango de Tarragona ''TarraTangueando'' es un festival de danza y música de tango organizado por la Asociación Cultural Espacio de Tango que se celebra anualmente la primera semana de agosto en la ciudad de Tarragona (Cataluña, España). Tanto el Tango como Tarragona son considerados…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Tango_de_Tarragona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184157,'17079','Festival Internacional de Teatro Amateur de Gerona','festival','festivales_wiki','El Festival Internacional de Teatro Amateur de Gerona (FITAG) es un festival anual de teatro aficionado que tiene lugar en Gerona desde septiembre de 1998.​',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Teatro_Amateur_de_Gerona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184158,'06018','Festival Internacional de Teatro Clásico de Mérida','festival','festivales_wiki','El Festival Internacional de Teatro Clásico de Mérida es un festival de teatro clásico que se celebra cada año en Mérida, España, durante los meses de julio y agosto en el Teatro Romano de Mérida. Inaugurado como reunión y certamen teatral en 1933, está considerado como uno de los más importantes en su género.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Teatro_Clásico_de_Mérida');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184159,'08023','Festival Internacional de Teatro de Sitges','festival','festivales_wiki','El Festival Internacional de Teatro de Sitges​ fue un festival de teatro que se organizó en Sitges desde 1967 hasta el 2004.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Teatro_de_Sitges');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184160,'08003','Festival Internacional de la Canción de Barcelona','festival','festivales_wiki','El Festival Internacional de la Canción de Barcelona fue un festival de canción ligera creado en 1968 como continuador del Festival de la Canción Mediterránea. Se celebró coincidiendo con las Fiestas de la Mercè de la capital catalana durante dos años, 1968 y 1969. Tuvo escasa repercusión por no contar con la…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_la_Canción_de_Barcelona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184161,'03007','Festival Internacional de la Canción de Benidorm','festival','festivales_wiki','El Festival Internacional de la Canción de Benidorm, conocido hasta 2003 como Festival Español de la Canción de Benidorm, y popularmente como Festival de Benidorm, fue un certamen musical organizado anualmente en la ciudad de Benidorm (Alicante, España) cada julio entre 1959 y 2006. Basado en el Festival de la…',38.53416667,-0.13138889,'https://es.wikipedia.org/wiki/Festival_Internacional_de_la_Canción_de_Benidorm');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184162,'06010','Festival Internacional de la Sierra','festival','festivales_wiki','El Festival Internacional de la Sierra FESTISIERRA se crea en el año 1980 con el sobrenombre de Festival de Bailes y Canciones Populares de Extremadura y desde entonces lleva celebrándose en la localidad de Fregenal de la Sierra cada año y siendo declarado en el 2018 Fiestas de Interés Turístico Nacional (España).…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_la_Sierra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184163,'90879','Festival Internacional de las Artes de Castilla y León','festival','festivales_wiki','El Festival Internacional de las Artes de Castilla y León (FÀCYL) es un evento multidisciplinar (teatro-danza, música electrónica, teatro multimedia, performances, danza, etc.) que se celebra anualmente en junio en Salamanca, España. Las fechas de celebración del festival están alrededor de las fiestas de San Juan…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_las_Artes_de_Castilla_y_León');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184164,'29069','Festival Internacional de Ópera de Marbella','festival','festivales_wiki','El Festival Internacional de Ópera de Marbella es un festival celebrado en Marbella, en la provincia de Málaga, España. El festival ofrece óperas clásicas como Rigoletto, de Giuseppe Verdi; Madame Butterfly, de Giacomo Puccini; Lucía de Lammermour, de Donizetti; o Carmen, de Bizet. Entre los artistas que han pasado…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Internacional_de_Ópera_de_Marbella');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184165,'46250','Festival La Cabina','festival','festivales_wiki','El Festival La Cabina es un Festival Internacional de Mediometrajes (películas de entre 30 y 60 minutos) celebrado anualmente en Valencia, España. Es el único festival de mediometrajes celebrado en España y se creó en 2008. Tiene una sección con mediometrajes a competición (Sección Oficial) y exhibe otros…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_La_Cabina');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184166,'37011','Festival Luz y Vanguardias','festival','festivales_wiki','El Festival Luz y Vanguardias es una muestra anual que se celebra en Salamanca desde 2016 en la que se dan cita obras de arte que tienen la luz como protagonista, incluyendo vídeos e instalaciones. Tiene como edificios singulares de la ciudad, sobre los que una selección de artistas jóvenes procedentes de las…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Luz_y_Vanguardias');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184167,'32054','Festival MITEU','festival','festivales_wiki','El Festival MITEU, también conocido como La MITEU, en femenino, por ser el acrónimo de Muestra Internacional de Teatro Universitario es un certamen de exhibición de piezas de teatro independiente -principalmente teatro universitario o académico- que se realiza anualmente durante dos semanas en el mes de abril en…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_MITEU');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184168,'08003','Festival MUTIS','festival','festivales_wiki','El Festival MUTIS de teatro independiente y nueva creación es una muestra participativa celebrada en Barcelona desde 2010 cada equinoccio de primavera, en la que confluyen actividades relacionadas con las artes escénicas interpretadas por compañías emergentes y grupos universitarios, principalmente españoles.​',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_MUTIS');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184169,'02001','Festival Nacional de Bandas de Música de Albacete','festival','festivales_wiki','El Festival Nacional de Bandas de Música de Albacete es un evento musical que se celebra anualmente en la ciudad española de Albacete.​​​ Nació en 1911 y en 2011 el festival alcanzó su 100.ª edición. Organizado por la Banda Sinfónica Municipal de Albacete, en él participan las mejores bandas de música de España,…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Nacional_de_Bandas_de_Música_de_Albacete');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184170,'37243','Festival Nacional de la Jota','festival','festivales_wiki','El Festival Nacional de la Jota es un certamen español de música y baile en torno a la jota castellana que se celebra cada año en la villa segoviana de Cuéllar, Castilla y León, y cuya primera edición fue realizada en 1968. Su primera edición tuvo lugar durante los encierros de Cuéllar de 1968, estuvo organizada…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Nacional_de_la_Jota');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184171,'28079','Festival Noches del Botánico','festival','festivales_wiki','El Festival Noches del Botánico es un Festival de Música que se celebra todos los años, desde 2016, durante los meses de junio y julio en el Real Jardín Botánico Alfonso XIII de la Universidad Complutense de Madrid. Los géneros musicales que se representan en el Festival son sobre todo Pop, Rock, Jazz, Música…',40.44797836,-3.72717123,'https://es.wikipedia.org/wiki/Festival_Noches_del_Botánico');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184172,'90341','Festival Paradiso de Barrax','festival','festivales_wiki','El Festival de Cine Paradiso de Barrax es un certamen cinematográfico nacional de cortometrajes. Se celebra anualmente en el mes de julio en el municipio español de Barrax (Albacete). Su primera edición arrancó en 2005.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Paradiso_de_Barrax');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184173,'22125','Festival Pirineos Sur','festival','festivales_wiki','Pirineos Sur es un festival musical y cultural que se organiza anualmente en la localidad de Lanuza, en Huesca, España. A lo largo de dos semanas se realizan diversos conciertos así como exposiciones, talleres, mercados y pasacalles.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Pirineos_Sur');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184174,'34003','Festival Ponte Louco','festival','festivales_wiki','El Festival Ponte Louco es un festival musical gratuito que se celebra desde el año 2001 en el castillo de Castro Caldelas (Orense, España). Está ligado a otras actuaciones lúdico-culturales como teatro, malabares, feria de artesanía. Se celebra en el mes de agosto, generalmente el primer sábado después del 15.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Ponte_Louco');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184175,'36035','Festival PortAmérica','festival','festivales_wiki','PortAmérica es un festival de música que se celebra anualmente en la Azucreira del municipio pontevedrés de Portas, en Galicia (España). El festival nació en 2012 y se celebró durante cinco ediciones en Nigrán. Para la edición de 2017 el festival se traslada a Caldas de Reyes,​ donde se celebraron tres ediciones.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_PortAmérica');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184176,'90200','Festival Reggaeboa','festival','festivales_wiki','El Reggaeboa Festival es un festival de música español de música reggae, y de diferentes estilos de música con origen en Jamaica (ska, dub, dancehall…), que se celebra con carácter anual desde el año 2010 en la localidad berciana de Balboa, provincia de León. Es un festival que une la música, las artesanías, el…',42.70638889,-6.92305556,'https://es.wikipedia.org/wiki/Festival_Reggaeboa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184177,'22254','Festival Rock Zaidín','festival','festivales_wiki','El Festival de Rock del Zaidín o Zaidín Rock, se celebra al aire libre en distintas plazas y calles del barrio del Zaidín en Granada y marca el final del verano y la acogida de la población universitaria por la ciudad. Fue creado en 1983 por la Asociación de Vecinos Zaidín-Vergeles y es organizado desde entonces…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Rock_Zaidín');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184178,'09473','Festival SOS 4.8','festival','festivales_wiki','El Festival Estrella Levante SOS 4.8 fue un festival internacional de acción artística sostenible que tuvo lugar en la ciudad de Murcia, España el primer fin de semana del mes de mayo, y desde su primera edición se realizó en el recinto ferial "La Fica", junto al Auditorio y Centro de Congresos Víctor Villegas. Es…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_SOS_4.8');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184179,'29083','Festival Sacro-Ritual de Riogordo','festival','festivales_wiki','El Festival Sacro-Ritual es un festival celebrado en Riogordo, en la provincia de Málaga, España. Se trata de un festival que pretende mantener y promocionar la tradición de la antigua liturgia escénica, en el que se mezclan el teatro, la música y la danza con exposiciones y actividades didácticas. Aunque el…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Sacro-Ritual_de_Riogordo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184180,'07005','Festival She Makes Noise','festival','festivales_wiki','She Makes Noise es un festival de música y cine, dedicado a mujeres y persones no binarias que trabajan en los campos de la música electrónica, el arte sonoro y la experimentación audiovisual. Su primera edición se celebró en el año 2015 y tiene una periodicidad anual.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_She_Makes_Noise');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184181,'10037','Festival Solidario de Cine Español de Cáceres','festival','festivales_wiki','El Festival Solidario de Cine Español de Cáceres es un festival celebrado en Cáceres cuyo objetivo es la promoción del cine español mediante proyecciones, libros, revistas, talleres y congresos, así como la donación de todos los beneficios generados a diferentes ONG extremeñas. Culmina con la entrega de los Premios…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Solidario_de_Cine_Español_de_Cáceres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184182,'90551','Festival Terral','festival','festivales_wiki','El Festival Terral, Terral Málaga o Festival de Verano Terral, es un festival de música que se celebra anualmente durante el mes de julio (es decir cuando sopla el terral) en la ciudad de Málaga, España. El festival está organizado por el Teatro Cervantes, escenario en el que tienen lugar la mayor parte de los…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Terral');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184183,'41091','Festival Zomos Heavyllanos','festival','festivales_wiki','El festival Zomos Heavyllanos se lleva celebrando en todos los años en octubre desde 2004 en la ciudad de Sevilla, con el objetivo de recaudar fondos para niños desfavorecidos. La palabra progreso no tiene ningún sentido mientras haya niños infelices.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_Zomos_Heavyllanos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184184,'32002','Festival barroco de músicas y comedias','festival','festivales_wiki','El festival barroco de músicas y comedias es un festival celebrado en Antequera, en la provincia de Málaga, España.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_barroco_de_músicas_y_comedias');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184185,'02001','Festival de Albacete','festival','festivales_wiki','El Festival de Albacete es un festival de música, teatro y danza que se celebra anualmente desde 1955 en la ciudad española de Albacete.​​​​ El evento tiene lugar en verano, entre agosto y septiembre.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Albacete');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184186,'36011','Festival de Cans','festival','festivales_wiki','El Festival de Cans es un festival de cortometrajes que se celebra anualmente en la parroquia española de Cans en el municipio de Porriño (Pontevedra). En sus inicios coincidía en fechas con el Festival de Cannes, a finales de mayo, y la idea de crearlo surgió de la similitud entre los nombres de ambas localidades.…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cans');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184187,'14021','Festival de Cine Africano de Córdoba 2012','festival','festivales_wiki','El Festival de Cine Africano de Córdoba celebró su novena edición desde el 13 hasta 20 de octubre de 2012. Tras ocho ediciones celebradas en Tarifa, el festival se realizó en el 2012 en Córdoba, situada en Andalucía, España. Una semana dedicada al cine de 28 países de África y el Medio Oriente.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_Africano_de_Córdoba_2012');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184188,'11035','Festival de Cine Africano de Tarifa-Tánger','festival','festivales_wiki','El Festival de Cine Africano (FCAT) es un festival anual dedicado a la cinematografía africana organizado por la asociación sin ánimo de lucro Al Tarab. Fundado por Mane Cisneros en el 2004 con el nombre de Muestra de Cine Africano de Tarifa, para cambiar su denominación de Muestra a Festival en la edición del 2007.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_Africano_de_Tarifa-Tánger');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184189,'08003','Festival de Cine Asiático de Barcelona','festival','festivales_wiki','BAFF: «Festival de cine asiático anual que se celebra en la ciudad de Barcelona», presenta las mejores películas de los diferentes países asiáticos, desde la India hasta Japón. Anualmente presentan a nuevos directores, los cuales entran en la Sección Oficial. El máximo premio es el Durián de Oro, otorgado por Casa…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_Asiático_de_Barcelona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184190,'29067','Festival de Cine Español de Tánger','festival','festivales_wiki','El Festival de Cine Español de Tánger es un festival de cine que surge en 2007 como una extensión del Festival de Málaga, siendo una iniciativa del Ayuntamiento de Málaga y del Ministerio de Asuntos Exteriores de España. Se integra dentro del Proyecto EDO (Entre Dos Orillas), dedicado a la cooperación artística e…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_Español_de_Tánger');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184191,'41091','Festival de Cine Europeo de Sevilla','festival','festivales_wiki','El Festival de Cine Europeo de Sevilla (en inglés: Seville European Film Festival o SEFF) se celebra anualmente, cada noviembre, desde el 2004.​ Lo organiza el Instituto de la Cultura y las Artes del Ayuntamiento de Sevilla. El primer premio es el Giraldillo de Oro a la Mejor Película de la Sección Oficial. En la…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_Europeo_de_Sevilla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184192,'41091','Festival de Cine Europeo de Sevilla 2009','festival','festivales_wiki','La 6.ª edición del Festival de Cine Europeo de Sevilla (Seville European Film Festival o SEFF) se celebró en la capital andaluza del 6 al 14 de noviembre de 2009.​',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_Europeo_de_Sevilla_2009');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184193,'41091','Festival de Cine Europeo de Sevilla 2010','festival','festivales_wiki','La 7.ª edición del Festival de Cine Europeo de Sevilla (en inglés: Seville European Film Festival o SEFF) se celebró en la capital andaluza del 5 al 13 de noviembre de 2010.​',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_Europeo_de_Sevilla_2010');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184194,'41091','Festival de Cine Europeo de Sevilla 2011','festival','festivales_wiki','La 8.ª edición del Festival de Cine Europeo de Sevilla (Seville European Film Festival o SEFF) se celebró en la capital andaluza del 4 al 11 de noviembre de 2011.​',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_Europeo_de_Sevilla_2011');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184195,'41091','Festival de Cine Europeo de Sevilla 2012','festival','festivales_wiki','La 9.ª edición del Festival de Cine Europeo de Sevilla (Seville European Film Festival o SEFF) se celebró en la capital andaluza del 2 al 10 de noviembre de 2012.​',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_Europeo_de_Sevilla_2012');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184196,'41091','Festival de Cine Europeo de Sevilla 2013','festival','festivales_wiki','La 10.ª edición del Festival de Cine Europeo de Sevilla (Seville European Film Festival o SEFF) se celebró en la capital andaluza entre el 8 y el 16 de noviembre de 2013.​',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_Europeo_de_Sevilla_2013');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184197,'29067','Festival de Cine Fantástico de Málaga','festival','festivales_wiki','FANCINE o Festival de Cine Fantástico de la Universidad de Málaga, es una muestra cinematográfica que se celebra en la ciudad de Málaga (España), especializado en el cine de género fantástico, ciencia ficción, misterio y de terror. El evento, que se desarrolla anualmente durante el mes de noviembre, está…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_Fantástico_de_Málaga');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184198,'35016','Festival de Cine Fantástico y Terror de Las Palmas de Gran Canaria','festival','festivales_wiki','Festival de Cine Fantástico y Terror de Las Palmas de Gran Canaria es un festival de cine que se celebra en Las Palmas de Gran Canaria (Gran Canaria; Canarias; España) dedicado al cine fantástico y de terror. En su primera edición (año 2000) contó con el patrocinio del canal temático Calle 13 y de la operadora de…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_Fantástico_y_Terror_de_Las_Palmas_de_Gran_Canaria');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184199,'29067','Festival de Cine Francés de Málaga','festival','festivales_wiki','El Festival de Cine Francés de Málaga (FCFM), es una muestra cinematográfica celebrada anualmente en la ciudad de Málaga, España.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_Francés_de_Málaga');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184200,'21041','Festival de Cine Iberoamericano de Huelva','festival','festivales_wiki','El Festival de Cine Iberoamericano de Huelva se celebra desde 1974 en la ciudad española de Huelva y está dedicado al cine iberoamericano (fundamentalmente creado en países americanos y europeos, del habla hispana y portuguesa global, en esencia). Entre sus objetivos está promocionar el cine iberoamericano en…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_Iberoamericano_de_Huelva');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184201,'28079','Festival de Cine Italiano de Madrid','festival','festivales_wiki','El Festival de Cine Italiano de Madrid es un Festival de cine que se tiene cada fin de año. Es organizado por Cinecittà Luce desde su primera edición que tuvo lugar en el 2008. Cuenta con una selección de películas presentadas en los festivales de Venecia, de Cannes, de Locarno, de Toronto y de Roma.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_Italiano_de_Madrid');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184202,'41091','Festival de Cine Lésbico y Gai de Andalucía','festival','festivales_wiki','El Festival de Cine Lésbico, Gai, bisexual y transexual de Andalucía, también llamado AndaLesGai, es un festival cinematográfico de temática LGBT celebrado anualmente en Andalucía desde el año 2006. Se trata del único festival de cine LGTB en la comunidad autónoma. El festival se desarrolla principalmente en…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_Lésbico_y_Gai_de_Andalucía');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184203,'29001','Festival de Cine de Alcalá de Henares','festival','festivales_wiki','El Festival de Cine de Alcalá de Henares (ALCINE) es un certamen cinematográfico de cortometrajes, fundado en 1970. Se celebra anualmente, durante el mes de noviembre, en Alcalá de Henares (Comunidad de Madrid). Está considerado uno de los festivales de cortometrajes más importantes de España.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_de_Alcalá_de_Henares');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184204,'26002','Festival de Cine de Astorga','festival','festivales_wiki','El Festival de Cine de Astorga es un certamen cinematográfico que se celebra anualmente a principios del mes de septiembre en la ciudad leonesa de Astorga (España). Su primera edición tuvo lugar en 1998.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_de_Astorga');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184205,'30016','Festival de Cine de Cartagena (España)','festival','festivales_wiki','El Festival Internacional de Cine de Cartagena (España), también conocido como FICC, es un certamen cinematográfico de carácter internacional que se lleva a cabo desde el año 1972 en la ciudad de Cartagena. Es el certamen cinematográfico más antiguo de la Región de Murcia.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_de_Cartagena_(España)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184206,'50151','Festival de Cine de Islantilla','festival','festivales_wiki','El Festival de Cine de Islantilla es un certamen cinematográfico que se celebra en Islantilla. Tiene lugar anualmente los meses completos de julio y agosto. Su nombre actual es Festival Internacional de Cine Bajo la Luna - Islantilla Cinefórum.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_de_Islantilla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184207,'03119','Festival de Cine de San Juan de Alicante','festival','festivales_wiki','El Festival de Cine Sant Joan d''Alacant es un festival cinematográfico fundado por el IES Luis García Berlanga en el año 2001, y cuyo actual promotor es el Ayuntamiento de San Juan de Alicante, siendo su sede principal la Casa de la Cultura municipal. Desde 2016, el Festival de Cine Sant Joan d''Alacant se incluye…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_de_San_Juan_de_Alicante');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184208,'08023','Festival de Cine de Sitges','festival','festivales_wiki','El Festival de Cine de Sitges (conocido también como Festival de Sitges o Festival Internacional de Cine Fantástico de Cataluña) es uno de los eventos cinematográficos más reconocidos de Europa, es el primer festival de cine fantástico del mundo y constituye, al mismo tiempo, la manifestación cultural con más…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_de_Sitges');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184209,'08023','Festival de Cine de Sitges de 2019','festival','festivales_wiki','La 52 edición del Festival de Cine de Sitges se celebró del 3 al 13 de octubre de 2019 en Sitges.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_de_Sitges_de_2019');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184210,'28079','Festival de Cine por mujeres','festival','festivales_wiki','El Festival de Cine por mujeres es un certamen cinematográfico que se celebra anualmente en Madrid (España) desde 2018.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cine_por_mujeres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184211,'08003','Festival de Cinema Budista de Catalunya','festival','festivales_wiki','El Festival de Cinema Budista de Catalunya (Festival de Cine Budista de Cataluña), conocido por sus siglas FCBC, es una muestra no competitiva de cine que se celebra en Barcelona, y cuya primera edición fue en 2022.',41.4042201,2.1551139,'https://es.wikipedia.org/wiki/Festival_de_Cinema_Budista_de_Catalunya');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184212,'11020','Festival de Cortometrajes de Jerez','festival','festivales_wiki','El Festival de Cortometrajes de Jerez es un festival de cortos dirigido a jóvenes realizadores celebrado en el mes de octubre en Jerez de la Frontera (Andalucía, España). Fundado en el año 2000, en su última edición se sobrepasaron los 180 cortometrajes enviados desde diferentes puntos de España, de los cuales 29…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Cortometrajes_de_Jerez');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184213,'48020','Festival de Escuelas de Teatro de Bilbao','festival','festivales_wiki','El Festival de Escuelas de Teatro de Bilbao, Festival de Teatro Universitario de Bilbao, Festival FETABI o simplemente FETABI​ es un festival internacional de teatro universitario que se celebra cada año en la ciudad de Bilbao. El festival se celebra anualmente en la ciudad de Bilbao y en él distintas compañías y…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Escuelas_de_Teatro_de_Bilbao');
