INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184215,'18087','Festival de Granada Cines del Sur','festival','festivales_wiki','Cines del Sur es un festival internacional de cine ubicado en Granada (España), que se ocupa de cinematografías emergentes adscritas al denominado sur geopolítico. Producciones fílmicas (asiáticas, africanas y latinoamericanas) que difícilmente cuentan con espacios de distribución y exhibición, encuentran en Cines…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Granada_Cines_del_Sur');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184216,'08279','Festival de Jazz Tarrasa','festival','festivales_wiki','El Festival de Jazz Tarrasa es un evento musical, centrado en el jazz, que se celebra anualmente desde 1982 en la localidad catalana de Tarrasa, en la provincia de Barcelona. Reúne cada año, durante casi un mes, entre marzo y abril, a más de 250 artistas, desde jóvenes figuras emergentes hasta grandes figuras del…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Jazz_Tarrasa');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184217,'26098','Festival de Jazz de Munilla','festival','festivales_wiki','El Festival de Jazz de Munilla, también conocido como MuniJazz, es un festival de jazz que se celebra anualmente en la localidad riojana de Munilla desde 2004.​​​ Está organizado por la Asociación de Amigos de Munilla, una asociación sin ánimo de lucro creada en 1981 para organizar actividades culturales que…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Jazz_de_Munilla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184218,'29067','Festival de Málaga','festival','festivales_wiki','El Festival de Málaga es una muestra cinematográfica anual celebrada en Málaga, España. Proyecta los estrenos más relevantes del año del cine español, incluyendo documentales y cortometrajes. También concede premios a las mejores películas del año así como galardones honoríficos.',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Málaga');
