INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184240,'15061','Festival de Ortigueira','festival','festivales_wiki','El Festival Internacional do Mundo Celta de Ortigueira, también conocido como Festival de Ortigueira, es un festival anual gratuito de música folk tradicional de las naciones celtas, fundado en 1978 por el personal de la Escola de gaitas de Ortigueira. Se suele celebrar el segundo fin de semana de cada julio en la…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Ortigueira');
