INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184242,'90058','Festival de Santurtzi','festival','festivales_wiki','El Santurzine o Festival de Santurtzi es un certamen cinematográfico anual celebrado en Santurce, España. En cuatro secciones, nacionales e internacionales, exhibe cortometrajes, largometrajes y documentales, así como realiza acciones a nivel social y cultural​ en el municipio conectando hostelería, comercio,…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Santurtzi');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184243,'10037','Festival de Teatro Clásico de Cáceres','festival','festivales_wiki','El Festival de Teatro Clásico de Cáceres es un acontecimiento cultural que se celebra cada año en la localidad de Cáceres, en España, durante las noches del mes de junio.​ Este es uno de los principales festivales de teatro clásico que se celebran en Extremadura. Mientras que el Festival Internacional de Teatro…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_Teatro_Clásico_de_Cáceres');
