INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184247,'29901','Festival de cine fantástico de Torremolinos','festival','festivales_wiki','El Festival de cine fantástico de Torremolinos nace en el año 2011 de la mano privada de Asociación cultural Cinefans (entidad organizadora del evento hasta la actualidad).​ El evento lo fundaron 4 personas: Miguel Pedraza, David Pedraza, Francisca Fuentes y Concepción Fuentes​ aunque la idea surge de Miguel…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_cine_fantástico_de_Torremolinos');
