INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184249,'09001','Festival de cortometrajes Sonorama','festival','festivales_wiki','El Festival de cortometrajes Sonorama, inicialmente llamado "Concurso nacional de cortometrajes Sonorama", es un festival anual de cortometrajes que se celebró en la localidad burgalesa de Aranda de Duero (España) desde el año 2000 hasta 2012. Estaba organizado por la asociación cultural, y sin ánimo de lucro, Art…',41.6679,-3.7004,'https://es.wikipedia.org/wiki/Festival_de_cortometrajes_Sonorama');
