INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184251,'08003','Festival de la Canción Mediterránea','festival','festivales_wiki','19674 El Festival de la Canción Mediterránea se celebró en Barcelona desde 1959 hasta 1967, y participaron en él artistas de diversos países mediterráneos. El festival, que nació casi al mismo tiempo que el Festival Internacional de la Canción de Benidorm, impulsado como aquel por el éxito del Festival de Sanremo,…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_de_la_Canción_Mediterránea');
