INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184255,'30041','Festival del Cante de las Minas','festival','festivales_wiki','El Festival Internacional del Cante de las Minas es un certamen español de flamenco que se celebra cada año en La Unión, Región de Murcia, y cuya primera edición fue realizada el 13 de octubre de 1961.​ El festival nació como un concurso de canto gracias al impulso que dieron figuras como el cantaor Juanito…',NULL,NULL,'https://es.wikipedia.org/wiki/Festival_del_Cante_de_las_Minas');
