INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184257,'10143','Festivalino de Pescueza','festival','festivales_wiki','El Festivalino de Pescueza es un festival de música que se realiza en el municipio español de Pescueza (Cáceres). Tiene una periodicidad anual y se organiza en el mes de abril ininterrumpidamente desde 2008. A diferencia de los principales festivales de música de España se distingue por no organizarse en una ciudad…',NULL,NULL,'https://es.wikipedia.org/wiki/Festivalino_de_Pescueza');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184258,'38009','Festivalito','festival','festivales_wiki','El Festivalito, nombre por el que es más conocido el Festival Internacional de Cine Chico de Canarias-Isla de La Palma, es un festival cinematográfico que se celebra cada verano en La Palma, Islas Canarias (España), desde 2002. El certamen fue el primer festival internacional en incorporar los rodajes a su…',NULL,NULL,'https://es.wikipedia.org/wiki/Festivalito');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184259,'43123','Fiesta Mayor de Reus','festival','festivales_wiki','La Fiesta Mayor de Reus, (Fiesta Mayor de San Pedro) está considerada la fiesta más grande de Reus (Tarragona) España. Declarada Fiesta Patrimonial de Interés Nacional por la Generalidad de Cataluña, tiene decenas de actos, los cuales giran alrededor de la «tronada».​ Tiene lugar el día 29 de junio. Aunque las…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_Mayor_de_Reus');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184260,'10037','Fiesta de la Primavera de Cáceres','festival','festivales_wiki','La Fiesta de la Primavera de Cáceres es el mayor festival universitario no solo de Extremadura, sino de toda la zona suroeste del país. Se celebra coincidiendo cada año con los primeros días de la estación primaveral por parte de todos los estudiantes de la Universidad de Extremadura y atrae a público de todas las…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_la_Primavera_de_Cáceres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184261,'30030','Fiesta de las Cuadrillas','festival','festivales_wiki','La Fiesta de las Cuadrillas es un festival de música tradicional que se celebra el último domingo de enero en la pedanía caravaqueña de Barranda en la Región de Murcia.',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_de_las_Cuadrillas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184262,'28079','Fiesta del PCE','festival','festivales_wiki','La Fiesta del PCE es la fiesta que celebra anualmente el Partido Comunista de España (PCE) en Madrid. Tiene lugar durante el mes de septiembre, la tercera semana normalmente.​​ Es uno de los acontecimientos políticos y culturales del año en la capital de España, en el que se combinan actos de índole social,…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiesta_del_PCE');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184263,'43148','Fiestas de Santa Tecla','festival','festivales_wiki','Las Fiestas de Santa Tecla de Tarragona tienen lugar alrededor de la fecha del 23 de septiembre, jornada central de la celebración. Duran diez días completos más la noche entera del 22 al 23 de septiembre. Son la fiesta grande de la ciudad de Tarragona, y gozan de los reconocimientos de Fiestas de interés turístico…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_Santa_Tecla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184264,'08003','Fiestas de la Merced','festival','festivales_wiki','La Merced, en catalán La Mercè, es la fiesta mayor de la ciudad de Barcelona, España. Se celebra cada año alrededor del 24 de septiembre, día de la Virgen de la Merced. Dura cerca de una semana y tiene lugar en diversos espacios públicos de la ciudad.​ Reúne anualmente entre 1.5 y 2 millones de personas en torno a…',NULL,NULL,'https://es.wikipedia.org/wiki/Fiestas_de_la_Merced');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184265,'25061','Fotogramas en Corto','festival','festivales_wiki','Fotogramas en Corto es un festival de cortometrajes organizado por la revista Fotogramas. Se caracteriza por la posibilidad de que cualquier persona pueda presentar su cortometraje a concurso, aunque no todos los trabajos son exhibidos en la sala de proyección del festival, sino únicamente una selección…',NULL,NULL,'https://es.wikipedia.org/wiki/Fotogramas_en_Corto');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184266,'31022','Francisco de Aranaz Darrás','festival','festivales_wiki','Francisco de Aranaz Darrás (San Sebastián 1917 - San Sebastián 2010) fue un anticuario y promotor cultural español destacando su colaboración en la creación del Festival de Cine de San Sebastián.​',NULL,NULL,'https://es.wikipedia.org/wiki/Francisco_de_Aranaz_Darrás');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184267,'25164','Gargar Festival','festival','festivales_wiki','Gargar Festival de Murales y Arte Rural es un evento artístico dedicado al muralismo que se realiza desde el año 2016 en la localidad noguerense de Penelles, a los pies de la sierra de Bellmunt-Almenara.​​',41.758332,0.965141,'https://es.wikipedia.org/wiki/Gargar_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184268,'08003','Gran Premio Honorífico','festival','festivales_wiki','El Gran Premio Honorífico es entregado en el marco del Festival de Cine de Sitges o Festival Internacional de Cinema Fantàstic de Catalunya, que se celebra cada octubre en la ciudad costera de Sitges, a unos 40 km de Barcelona.​ Este premio se entrega a modo de homenaje a aquellos cineasta de cualquiera de las…',NULL,NULL,'https://es.wikipedia.org/wiki/Gran_Premio_Honorífico');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184269,'18087','Granada Noir','festival','festivales_wiki','Granada Noir son unas jornadas del género negro en todas sus vertientes -cómic, novela y cine-, enmarcadas dentro de las Semanas Negras de España, convocadas en el municipio de Granada (España) durante la primera semana del mes de octubre de la convocatoria correspondiente.​',NULL,NULL,'https://es.wikipedia.org/wiki/Granada_Noir');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184270,'18087','Granada Sound','festival','festivales_wiki','Granada Sound es un festival de música indie nacional e internacional. Se celebra en el Cortijo del Conde, en la ciudad de Granada (España), durante dos días del mes de septiembre. Su primera edición se lleva a cabo en el 2012, y se sigue celebrando hasta la actualidad contando ya con 10 ediciones.',NULL,NULL,'https://es.wikipedia.org/wiki/Granada_Sound');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184271,'35016','Granca Live Fest','festival','festivales_wiki','El Granca Live Fest es un festival de música que se celebra anualmente en Las Palmas de Gran Canaria, España. Su primera edición tuvo lugar en 2022 y se ha consolidado como uno de los principales eventos musicales de las Islas Canarias. El festival se desarrolla en el Estadio de Gran Canaria.​ El cartel del Granca…',NULL,NULL,'https://es.wikipedia.org/wiki/Granca_Live_Fest');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184272,'29067','Hotel Málaga Palacio','festival','festivales_wiki','El Hotel Málaga Palacio es un famoso hotel situado en el centro histórico de la ciudad de Málaga, España. Se adscribe a los principios del movimiento moderno, con un marcado carácter expresionista, que podría también encuadrarse en el movimiento conocido como "estilo del relax". Fue proyectado por Juan Jáuregui…',36.71888889,-4.41944444,'https://es.wikipedia.org/wiki/Hotel_Málaga_Palacio');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184273,'07026','International Music Summit','festival','festivales_wiki','International Music Summit (IMS) es una conferencia de música electrónica de baile (EDM) de tres días de duración que se celebra en Ibiza. Su fundador, Pete Tong, la describe como «un intenso ambiente de trabajo en red con el glamur y la ostentación de mi isla de fiesta favorita, Ibiza, pero con el espíritu de Back…',NULL,NULL,'https://es.wikipedia.org/wiki/International_Music_Summit');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184274,'29067','Irreconciliables Festival Internacional de Poesía de Málaga','festival','festivales_wiki','Irreconciliables Festival Internacional de Poesía de Málaga es un evento internacional anual de carácter cultural dedicado a la poesía​ que se celebra desde 2012 en la ciudad de Málaga. El festival nace por iniciativa de poetas malagueños y actualmente cuenta con el patrocinio del Ministerio de Educación, Cultura y…',NULL,NULL,'https://es.wikipedia.org/wiki/Irreconciliables_Festival_Internacional_de_Poesía_de_Málaga');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184275,'20069','Jazzaldia','festival','festivales_wiki','El Festival de Jazz de San Sebastián (en euskera, Donostiako Jazzaldia), más conocido como Jazzaldia, es un festival de jazz que se celebra anualmente la tercera semana de julio en la ciudad vasca de San Sebastián. Fundado en 1966, es el Festival de Jazz más antiguo de España y uno de los más antiguos de Europa. El…',43.32,-1.98,'https://es.wikipedia.org/wiki/Jazzaldia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184276,'23050','Jaén Subterránea','festival','festivales_wiki','Jaén Subterránea, también conocido como Festival Internacional de Teatro Alternativo de Jaén, fue un festival de creación escénica contemporánea celebrado anualmente entre el 2005 y el 2010 en la ciudad española de Jaén, en Andalucía. En sus cinco ediciones participaron colectivos y creadores de países como…',NULL,NULL,'https://es.wikipedia.org/wiki/Jaén_Subterránea');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184277,'21008','Jornadas de Teatro de Éibar','festival','festivales_wiki','Las Jornadas de Teatro de Éibar (España) comenzaron su andadura en la edición de 1977 y son organizadas desde el año 2013 por el Ayuntamiento de Éibar. Se celebran habitualmente entre mediados de febrero y mediados de marzo y sus sedes principales son el Teatro Coliseo y el Teatro del Complejo Educativo de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Jornadas_de_Teatro_de_Éibar');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184278,'20069','José Luis Rebordinos','festival','festivales_wiki','José Luis Rebordinos Miramón (Rentería, 1961) es un director español de festivales cinematográficos conocido por haber dirigido la Semana de Cine Fantástico y de Terror de San Sebastián, el Festival de Cine y Derechos Humanos de San Sebastián y, desde 2011, el Festival Internacional de Cine de San Sebastián.',NULL,NULL,'https://es.wikipedia.org/wiki/José_Luis_Rebordinos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184279,'36012','Kanina Rock','festival','festivales_wiki','El festival Kanina Rock es un evento anual de grupos de rock celebrado en el mes de agosto en la localidad onubense de La Redondela, España.​ La fecha suele coincidir con el tercer fin de semana de agosto.​ Su actividad, a diferencia de otros festivales, es diurna y nocturna, iniciándose la apertura de puertas con…',NULL,NULL,'https://es.wikipedia.org/wiki/Kanina_Rock');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184280,'08003','LOOP','festival','festivales_wiki','Loop Barcelona es una plataforma dedicada a la imagen en movimiento en el arte contemporáneo, que nació en 2003, en Barcelona, como la primera feria a nivel mundial dedicada exclusivamente al video arte. Tras 10 ediciones, la feria es reconocida internacionalmente como un referente en el arte audiovisual y un…',NULL,NULL,'https://es.wikipedia.org/wiki/LOOP');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184281,'18087','La Caña Flamenca','festival','festivales_wiki','La Caña Flamenca es un festival español de flamenco que se celebra anualmente desde el año 2018 en diferentes localidades de la comarca de la Costa Granadina, provincia de Granada.​',NULL,NULL,'https://es.wikipedia.org/wiki/La_Caña_Flamenca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184282,'30011','La Noche Blanca del Flamenco','festival','festivales_wiki','La Noche Blanca del Flamenco es un evento celebrado en Córdoba (España). Durante ese día se llevan a cabo por toda la ciudad, desde inicios de la noche hasta la madrugada, numerosos conciertos y actuaciones relacionadas con el flamenco con la presencia de grandes figuras del flamenco.',NULL,NULL,'https://es.wikipedia.org/wiki/La_Noche_Blanca_del_Flamenco');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184283,'06030','Lagarto Festival','festival','festivales_wiki','El Lagarto Festival (antaño Lagarto Rock) es un concurso musical de nivel nacional celebrado en el Auditorio de La Alameda, Jaén (España) durante las fiestas del mes de junio en honor a la Virgen de la Capilla.',NULL,NULL,'https://es.wikipedia.org/wiki/Lagarto_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184284,'30035','Leyendas del Rock','festival','festivales_wiki','Leyendas del Rock es un festival de música heavy metal y rock duro que se celebra anualmente desde 2006. Desde la primera edición hasta la de 2012 se celebró en los municipios murcianos de Mazarrón, San Javier y Beniel,​ y desde el año 2013 se celebra en la localidad de Villena.​ En los inicios del festival la gran…',NULL,NULL,'https://es.wikipedia.org/wiki/Leyendas_del_Rock');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184285,'49275','Little Opera Zamora','festival','festivales_wiki','LittleOpera Zamora (Pequeña Ópera Zamora) es un festival internacional de ópera de cámara que se celebra en la ciudad de Zamora, comunidad autónoma de Castilla y León, en España. Su principal característica es la muestra de óperas en su versión original, sin reducciones ni adaptaciones, en diferentes espacios de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Little_Opera_Zamora');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184286,'17095','Lloret Negre','festival','festivales_wiki','El Festival de Género Negro Lloret Negre (o simplemente Lloret Negre) es un evento cultural sin ánimo de lucro celebrado en la localidad de Lloret de Mar (Gerona, Cataluña). Tiene tres encuentros anuales dedicados a Literatura (generalmente en mayo - abril), Entrega de Premios de Literatura (en septiembre) y Film…',NULL,NULL,'https://es.wikipedia.org/wiki/Lloret_Negre');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184287,'18087','Lorca y Granada en los Jardines del Generalife','festival','festivales_wiki','Lorca y Granada en los Jardines del Generalife es un festival​ que rinde homenaje a la figura y la obra de Federico García Lorca. Su programación consiste en la puesta en escena de un único espectáculo, durante la segunda quincena de julio y el mes de agosto, en un número variable de funciones, en torno a treinta.…',NULL,NULL,'https://es.wikipedia.org/wiki/Lorca_y_Granada_en_los_Jardines_del_Generalife');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184288,'20069','Luis Gasca','festival','festivales_wiki','Luis María Francisco Gasca Burges (San Sebastián, 17 de septiembre de 1933 - 6 de julio de 2021)​ fue un editor estudioso español del cómic y el cine.',NULL,NULL,'https://es.wikipedia.org/wiki/Luis_Gasca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184289,'37011','Magosto','festival','festivales_wiki','El magosto, magüesto,​ magosta, magostu, magüestu, amagüestu o castanyada es una fiesta tradicional en algunas regiones del noroeste de España, como Galicia,​ Cantabria, Asturias, León,​norte de Palencia,​ Zamora,​​ Salamanca,​​ Cataluña y Cáceres (Las Hurdes, Carbajo),​ así como Canarias (Los Finaos).​ Se trata de…',NULL,NULL,'https://es.wikipedia.org/wiki/Magosto');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184290,'19130','Maratón de los Cuentos','festival','festivales_wiki','El Maratón de los Cuentos es un festival de narración oral que se realiza cada año en el palacio del Infantado de Guadalajara (España) durante el segundo o tercer fin de semana de junio. Reúne a contadores de cuentos o cuentacuentos de todo el mundo que narran de forma ininterrumpida durante el fin de semana.…',NULL,NULL,'https://es.wikipedia.org/wiki/Maratón_de_los_Cuentos');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184291,'26150','Mariporrón','festival','festivales_wiki','El Mariporrón fue un festival de música ska y reggae que se celebró anualmente entre 1998 y 2005 en la pequeña localidad riojana de Tormantos (España). Nació como una propuesta de los jóvenes de la localidad para animar las fiestas patronales. Cada año conseguía convocar a más gente venida de todo el país Los…',NULL,NULL,'https://es.wikipedia.org/wiki/Mariporrón');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184292,'46250','Medusa Sunbeach Festival','festival','festivales_wiki','El Medusa Sunbeach Festival es un festival de música electrónica. Se celebra desde 2014 cada año en la playa de Cullera, municipio de Valencia, Comunidad Valenciana. Encontramos diferentes estilos con sus respectivos escenarios: desde el EDM en el escenario principal hasta Techno, Indie, Remember, Hardstyle,…',NULL,NULL,'https://es.wikipedia.org/wiki/Medusa_Sunbeach_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184293,'08302','Memoria de mis putas tristes (película)','festival','festivales_wiki','Memoria de mis putas tristes es una película dramática mexicana de 2012 dirigida por Henning Carlsen y escrita por Carlsen y Jean-Claude Carriére, basada en la novela homónima de Gabriel García Márquez. Se filmó en formato de 35 milímetros en la ciudad de San Francisco de Campeche (Campeche). Es protagonizada por…',NULL,NULL,'https://es.wikipedia.org/wiki/Memoria_de_mis_putas_tristes_(película)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184294,'08003','Mercado de Música Viva de Vich','festival','festivales_wiki','El Mercado de Música Viva de Vic (en catalán, "Mercat de Música Viva de Vic"), también conocido por sus siglas MMVV, que se celebra en Vic (provincia de Barcelona) es uno de los eventos musicales más prestigiosos de Cataluña. Se celebra anualmente desde 1989, durante el mes de septiembre, y tiene una duración de…',NULL,NULL,'https://es.wikipedia.org/wiki/Mercado_de_Música_Viva_de_Vich');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184295,'25061','Metalway Festival','festival','festivales_wiki','Metalway es un festival musical dedicado exclusivamente al heavy metal y todas sus variantes, celebrado entre 2005 y 2009 en tierras españolas. La primera edición del festival se llevó a cabo en el año 2005, convirtiéndose en el sucesor del festival Metal Manía que se celebró entre 2003 y 2004.',NULL,NULL,'https://es.wikipedia.org/wiki/Metalway_Festival');
