INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184297,'33024','Metrópoli Gijón','festival','festivales_wiki','Metrópoli es un festival de música que se celebra de manera anual a finales del mes de junio y principios del mes de julio en el recinto ferial de la ciudad asturiana de Gijón, en el norte de España.',NULL,NULL,'https://es.wikipedia.org/wiki/Metrópoli_Gijón');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184298,'28045','Modorrock','festival','festivales_wiki','Modorrock es un Festival solidario de música organizado por la Asociación Colmenar Música Joven con el patrocinio del Ayuntamiento de Colmenar Viejo cuya recaudación va destinada a diferentes ONG. El festival tiene lugar desde el 2006 en la plaza de toros de Colmenar Viejo habiéndose celebrado ya su tercera edición…',NULL,NULL,'https://es.wikipedia.org/wiki/Modorrock');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184299,'08003','Monegros Desert Festival','festival','festivales_wiki','Monegros Desert Festival es un festival de música electrónica que se celebra en España, en el desierto de los Monegros (Huesca), entre las poblaciones de Candasnos y Fraga. Se centra en géneros como el techno, el electro, bass music o el drum and bass, así como también el hip-hop. Es organizado por la productora…',NULL,NULL,'https://es.wikipedia.org/wiki/Monegros_Desert_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184300,'15031','Morriña Fest','festival','festivales_wiki','El Morriña Fest es un festival de música que se celebra anualmente en la ciudad gallega de La Coruña (España) desde 2021. La primera edición tuvo lugar en el vecino municipio de Culleredo.',NULL,NULL,'https://es.wikipedia.org/wiki/Morriña_Fest');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184301,'46250','Mostra Viva del Mediterrani','festival','festivales_wiki','Mostra Viva del Mediterrani es un certamen que se celebra en Valencia, España. Reúne múltiples manifestaciones culturales de los diferentes pueblos de la cuenca mediterránea. Entre las disciplinas que abarca se encuentran: la música, la danza, el circo, la narración oral, la literatura, las artes visuales, los…',NULL,NULL,'https://es.wikipedia.org/wiki/Mostra_Viva_del_Mediterrani');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184302,'46250','Mostra de València','festival','festivales_wiki','Mostra de València-Cinema del Mediterrani es un certamen cinematográfico que cuenta con 38 ediciones y se desarrolla en la ciudad española de Valencia desde el año 1980. Normalmente se celebra durante el mes de octubre. Mostra de València-Cinema del Mediterrani volvió renovada en el 2018, tras seis años sin…',NULL,NULL,'https://es.wikipedia.org/wiki/Mostra_de_València');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184303,'22125','Motion Graphics Review','festival','festivales_wiki','La Motion Graphics Review es una sección fuera de competición del Festival de Cine de Huesca. Reúne cada año una selección de los gráficos generados por ordenador de estudios de todo el mundo divididos en cuatro categorías: ad in motion (piezas comerciales); music in motion (videoclips); personal in motion…',NULL,NULL,'https://es.wikipedia.org/wiki/Motion_Graphics_Review');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184304,'30016','Mucho Más Mayo','festival','festivales_wiki','Mucho Más Mayo (M+M o MMM) es un festival público de arte emergente celebrado en la ciudad española de Cartagena y organizado por el Ayuntamiento de Cartagena, a través de sus concejalías de Cultura y de Juventud. Desde sus comienzos, el festival ha servido como un laboratorio de proyectos culturales para la…',NULL,NULL,'https://es.wikipedia.org/wiki/Mucho_Más_Mayo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184305,'16009','Muestra Cinematográfica del Atlántico Alcances','festival','festivales_wiki','La Muestra Cinematográfica del Atlántico Alcances es un festival de cine que anualmente se celebra en la ciudad de Cádiz desde finales de los años 60 hasta la actualidad. Desde 2015 su nombre oficial es Festival de Cine Documental de Cádiz, Alcances. Con el deseo de enriquecer la oferta cultural gaditana, nace…',NULL,NULL,'https://es.wikipedia.org/wiki/Muestra_Cinematográfica_del_Atlántico_Alcances');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184306,'50297','Muestra Internacional de Cine realizado por Mujeres','festival','festivales_wiki','La Muestra Internacional de Cine Realizado por Mujeres de Zaragoza es una de las muestras de cine realizado por mujeres más consolidadas del Estado español, con veinticinco años de experiencia, que desde 1997 se celebra anualmente en la capital de Aragón.​ Organizada desde el Seminario Interdisciplinar de Estudios…',NULL,NULL,'https://es.wikipedia.org/wiki/Muestra_Internacional_de_Cine_realizado_por_Mujeres');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184307,'46110','Muestra Internacional de Payasas y Payasos de Xirivella','festival','festivales_wiki','La Muestra Internacional de Payasas y Payasos de Xirivella es un festival español especializado en el arte del payaso y la payasa, con sede en Chirivella, creado en 1993.',39.465556,-0.426667,'https://es.wikipedia.org/wiki/Muestra_Internacional_de_Payasas_y_Payasos_de_Xirivella');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184308,'25120','Muestra de Cine Latinoamericano de Cataluña','festival','festivales_wiki','La Muestra de Cine Latinoamericano de Cataluña (En catalán Mostra de Cinema Llatinoamericà de Catalunya) es un festival de cine que se realiza anualmente en Lérida, España. Se celebra desde 1995 y está dedicado al cine hispanoamericano. Está organizado por el Centro Latinoamericano de Lérida y su patrocinio corre a…',NULL,NULL,'https://es.wikipedia.org/wiki/Muestra_de_Cine_Latinoamericano_de_Cataluña');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184309,'32003','Muestra de cine andaluz y del Mediterráneo','festival','festivales_wiki','La Muestra de cine andaluz y del Mediterráneo, también llamada Archidona Cinema es una muestra de cine celebrada anualmente desde 2004 en la ciudad malagueña de Archidona (España). Está dedicada, como su nombre indica, al cine de Andalucía y los países ribereños del Mediterráneo. El festival se desarrolla durante…',NULL,NULL,'https://es.wikipedia.org/wiki/Muestra_de_cine_andaluz_y_del_Mediterráneo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184310,'08003','Musiclip festival','festival','festivales_wiki','Musiclip Festival, (también conocido como Musiclip, Festival Internacional de la Música, las Artes Audiovisuales y el Videoclip de Barcelona) es un evento anual que premia los mejores videoclips del año y que se celebra en la ciudad española de Barcelona desde el año 2007. Además del certamen de videos musicales,…',NULL,NULL,'https://es.wikipedia.org/wiki/Musiclip_festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184311,'20067','Musikaste','festival','festivales_wiki','Musikaste es la semana de la música vasca que se celebra anualmente en la localidad guipuzcoana de Rentería (País Vasco, España. Está dedicada fundamentalmente a la difusión de la creación musical de los compositores vasco-navarros.​ Fue fundada en 1973 por José Luis Ansorena, director de la Coral Andra Mari de…',43.31415833,-1.901225,'https://es.wikipedia.org/wiki/Musikaste');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184312,'48020','Música-Musika','festival','festivales_wiki','Música-Musika es un festival internacional de música celebrado de forma anual en Bilbao. La característica principal del Festival es su carácter temático ya que en cada una de sus ediciones las actuaciones se centran en una época, estilo o compositor concreto.​ Cada edición atrae a un importante número de…',NULL,NULL,'https://es.wikipedia.org/wiki/Música-Musika');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184313,'04008','Natural Music Festival','festival','festivales_wiki','El Natural Music Festival fue un festival de música, que aglutinaba diferentes estilos, entre los que predominaba la música alternativa y el rock, que se celebraba en la localidad de El Ejido (Almería, Andalucía, España). Nació en 2006, gracias al ayuntamiento de El Ejido y a la promotora Music Frog, y tuvo lugar…',NULL,NULL,'https://es.wikipedia.org/wiki/Natural_Music_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184314,'22249','No Surrender Festival','festival','festivales_wiki','No Surrender Festival es un evento en honor al músico estadounidense Bruce Springsteen organizado por Josep Maria Pons en el campo de fútbol de Villanova de Bellpuig, que se ha repetido desde 2017 hasta este año 2019 (superándose cada año ) a la espera de confirmación para este 2020 , un pequeño pueblo de la…',NULL,NULL,'https://es.wikipedia.org/wiki/No_Surrender_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184315,'11020','Noches de Bohemia (Jerez de la Frontera)','festival','festivales_wiki','Noches de Bohemia es un ciclo de músicas del mundo celebrado cada verano en Jerez de la Frontera (Andalucía, España). Este ciclo de músicas se creó con el objetivo de enriquecer la oferta cultural estival de Jerez de la Frontera. Los patrocinios principales proceden de instituciones y empresas locales, careciendo…',NULL,NULL,'https://es.wikipedia.org/wiki/Noches_de_Bohemia_(Jerez_de_la_Frontera)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184316,'31135','Notodofilmfest','festival','festivales_wiki','Notodofilmfest es un festival español de cortometrajes en Internet creado en el año 2001 por el cineasta Javier Fesser y es uno de los proyectos de la empresa de gestión cultural La Fábrica. Notodofilmfest es el mayor festival de cortos en España desde hace más de 20 años. Tiene como propósito potenciar el talento…',NULL,NULL,'https://es.wikipedia.org/wiki/Notodofilmfest');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184317,'36011','Novos Cinemas','festival','festivales_wiki','Novos Cinemas o Festival Internacional de Cine de Pontevedra es un festival de cine que se celebra durante una semana en el mes de diciembre en la ciudad española de Pontevedra.​​',NULL,NULL,'https://es.wikipedia.org/wiki/Novos_Cinemas');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184318,'08003','Ohlalà! Festival de cine francófono de Barcelona','festival','festivales_wiki','Ohlalà​! es el nombre del primer festival de cine francófono de Barcelona. Celebrado una vez al año desde 2018, se proyecta una selección de películas en el Institut français de Barcelona i en los Cines Texas durante aproximadamente una semana, algunas recompensadas por premios al final del festival.',NULL,NULL,'https://es.wikipedia.org/wiki/Ohlalà!_Festival_de_cine_francófono_de_Barcelona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184319,'28079','PHotoESPAÑA','festival','festivales_wiki','PHotoESPAÑA es un festival internacional de fotografía que se celebra cada año en Madrid durante los meses de junio, julio, agosto y septiembre. Este festival, fundado por Alberto Anaut, comenzó su andadura en 1998 y ha ido creciendo y consolidándose hasta convertirse en una cita de referencia para el mundo de las…',NULL,NULL,'https://es.wikipedia.org/wiki/PHotoESPAÑA');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184320,'33024','Pantalla para un debate','festival','festivales_wiki','Pantalla para un debate es un espacio impulsado por la Tertulia Feminista Les Comadres en el marco del Festival Internacional de Cine de Gijón iniciado en 1997.',NULL,NULL,'https://es.wikipedia.org/wiki/Pantalla_para_un_debate');
