INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184322,'08005','Patum de Berga','festival','festivales_wiki','La Fiesta de la Patum de Berga es una celebración tradicional que se realiza durante las fiestas del Corpus Christi en la localidad catalana de Berga. Ha sido declarada por la Unesco Patrimonio Cultural Inmaterial de la Humanidad el día 25 de noviembre del año 2005 e inscrita en 2008 en su lista representativa​ y…',42.104342,1.846237,'https://es.wikipedia.org/wiki/Patum_de_Berga');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184323,'09361','Petróleo Rock','festival','festivales_wiki','El Festival Petróleo Rock es un festival de música rock que se celebraba en la localidad burgalesa de Miranda de Ebro desde 2007 hasta 2009. Las ediciones anteriores, la 2005 y 2006, se celebraron en Sargentes de la Lora (Burgos) reuniendo menos participación que en las ediciones más recientes. Su principal…',NULL,NULL,'https://es.wikipedia.org/wiki/Petróleo_Rock');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184324,'46250','Pirata Beach Festival','festival','festivales_wiki','Pirata Beach Festival (anteriormente conocido como Pirata Rock Festival) ​ es un festival de música que se celebra en el Polígono Benieto en la localidad de Gandía (provincia de Valencia, España) durante el mes de julio.​ La primera edición se llevó a cabo en 2017 con artistas como La Pegatina, ToteKing y Auxili.​…',NULL,NULL,'https://es.wikipedia.org/wiki/Pirata_Beach_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184325,'39052','Piélagos en Corto','festival','festivales_wiki','El Festival Internacional de Cine Piélagos en Corto es un festival de cine anual que se celebra en el municipio de Piélagos, Cantabria. Proyecta cortometrajes y largometrajes tanto nacionales como internacionales. También concede premios a empresas, instituciones o personalidades relacionadas con el mundo del cine,…',NULL,NULL,'https://es.wikipedia.org/wiki/Piélagos_en_Corto');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184326,'36011','Play-Doc Festival Internacional de Cine de Tui','festival','festivales_wiki','Play-Doc Festival Internacional de Cine de Tui , es un festival de cine de no-ficción que se celebra anualmente a finales de abril o principios de mayo en Tuy (Pontevedra) desde el año 2005. Fue fundado y está codirigido por Sara García Villanueva y Ángel Sánchez.',NULL,NULL,'https://es.wikipedia.org/wiki/Play-Doc_Festival_Internacional_de_Cine_de_Tui');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184327,'17079','PopArb','festival','festivales_wiki','popArb es un festival de música independiente hecha en Cataluña, celebrado desde 2005 en Arbucias, un pueblo de la provincia de Gerona (España).​',NULL,NULL,'https://es.wikipedia.org/wiki/PopArb');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184328,'36015','Premio Jean Vigo (España)','festival','festivales_wiki','El Festival Punto de Vista entrega desde febrero de 2007 el Premio Jean Vigo al Mejor Director de cuantos participan en la Sección Oficial Competitiva del festival.',NULL,NULL,'https://es.wikipedia.org/wiki/Premio_Jean_Vigo_(España)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184329,'33024','Premio Rambal','festival','festivales_wiki','El Premio Rambal es un galardón que se entrega en el Festival Internacional de Cine de Gijón (FICX) desde 2021 para reconocer a cineastas y/o producciones LGTBI que participen en el certamen.​',NULL,NULL,'https://es.wikipedia.org/wiki/Premio_Rambal');
