INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184332,'09180','Purple Weekend','festival','festivales_wiki','El Purple Weekend es un festival mod sesentero de España. Se desarrolla en León y fue fundado por Alejandro Díez y Elena Iglesias (cantante y teclista de Los Flechazos respectivamente). Después del éxito de este festival dedicado a la cultura "sixties" han aparecido otros como el EuroYeyé de Gijón o el Beat Goes On…',NULL,NULL,'https://es.wikipedia.org/wiki/Purple_Weekend');
