INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184334,'20069','Quincena Musical de San Sebastián','festival','festivales_wiki','La Quincena Musical de San Sebastián (en euskera: Donostiako Musika Hamabostaldia) es un festival de música clásica, que se celebra cada año en el mes de agosto desde 1939 en la ciudad vasca de San Sebastián, España. Se trata del festival de música más antiguo de España y uno de los más antiguos de Europa. La…',NULL,NULL,'https://es.wikipedia.org/wiki/Quincena_Musical_de_San_Sebastián');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184335,'12100','Rebujas Rock','festival','festivales_wiki','El Rebujas Rock fue un festival de música rock que se celebró cada mes de septiembre en el pueblo de San Mateo, Cantabria desde 1997 hasta 2021.',NULL,NULL,'https://es.wikipedia.org/wiki/Rebujas_Rock');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184336,'04065','Resurrection Fest','festival','festivales_wiki','El Resurrection Fest es un festival de música que tiene lugar en la parroquia de Celeiro, en el municipio de Viveiro, en la provincia de Lugo, España. Este festival, también popularmente conocido en España como El Resu, se celebra desde 2006 anualmente durante el verano, con un programa musical centrado en la…',NULL,NULL,'https://es.wikipedia.org/wiki/Resurrection_Fest');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184337,'08180','Ripollet Rock Festival','festival','festivales_wiki','El Ripollet Rock Festival es un festival de rock y hard rock en todas sus variantes que se celebra cada año desde 1993 en Ripollet, Barcelona, coincidiendo con la Fiesta Mayor a finales de agosto. Está organizado por la Asociación Ripollet Rock. La entrada es gratuita.',NULL,NULL,'https://es.wikipedia.org/wiki/Ripollet_Rock_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184338,'08245','Rock Fest BCN','festival','festivales_wiki','El Rock Fest Barcelona es un festival de música de rock y heavy metal celebrado en verano, principalmente en el mes de julio, en el Parque de Can Zam, en la ciudad de Santa Coloma de Gramanet.​ El festival nació con el objetivo de llenar el hueco de festivales de este estilo en la zona de la ciudad de Barcelona.​…',NULL,NULL,'https://es.wikipedia.org/wiki/Rock_Fest_BCN');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184339,'30016','Rock Imperium Festival','festival','festivales_wiki','Rock Imperium Festival es un festival dedicado a la música heavy metal y al rock duro en Cartagena, que se celebra anualmente desde 2022 generalmente a finales del mes de junio. Concretamente en el Parque de la Cuesta del Batel de Cartagena (Región de Murcia).',37.60117906,-0.97753338,'https://es.wikipedia.org/wiki/Rock_Imperium_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184340,'18087','Rocket Festival','festival','festivales_wiki','El Rocket Festival es un festival musical organizado anualmente, en el mes de mayo, cerca de Granada, Andalucía (España). Se viene organizando desde el año 2005 y en él se dan cita artistas del panorama musical alternativo europeo. El Rocket Festival es una celebración alternativa de la vida y de la cultura, una…',NULL,NULL,'https://es.wikipedia.org/wiki/Rocket_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184341,'29901','Rockin'' Race Jamboree','festival','festivales_wiki','Rockin'' Race Jamboree es un festival dedicado a la música y cultura del rock and roll, rockabilly y la de estilos afines, que combina conciertos en directo con actividades vinculadas a la estética y el ocio estadounidense de mediados del siglo XX. Se lleva a cabo anualmente en la localidad turística de…',NULL,NULL,'https://es.wikipedia.org/wiki/Rockin''_Race_Jamboree');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184342,'12028','Rototom Sunsplash','festival','festivales_wiki','El Rototom Sunsplash es un festival reggae, fundado en 1994 en Gaio di Spilimbergo, en la provincia italiana de Pordenone, y que desde 2010 se celebra en la localidad española de Benicasim (Castellón). Se le considera el festival más importante de su género en Europa y en 2010 recibió el reconocimiento y patrocinio…',NULL,NULL,'https://es.wikipedia.org/wiki/Rototom_Sunsplash');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184343,'12028','SanSan Festival','festival','festivales_wiki','El SanSan Festival es un festival de música indie, pop y rock nacional, aunque también cuenta con la presencia, en menor medida, de grupos internacionales. Con siete ediciones a sus espaldas, tiene lugar en la población de Benicasim cada Semana Santa, aunque las tres primeras ediciones se llevaron a cabo en…',NULL,NULL,'https://es.wikipedia.org/wiki/SanSan_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184344,'17160','Sant Feliu Fest','festival','festivales_wiki','Sant Feliu Fest es un festival de música independiente y do it yourself organizado por la Atzavara Club en San Felíu de Guixols desde el año 1997, denominado al comienzo Sant Feliu Hardcore Fest atendida su relación con la música hardcore punk y sus variantes: hardcore melódico, post-hardcore, screamo, grindcore o…',NULL,NULL,'https://es.wikipedia.org/wiki/Sant_Feliu_Fest');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184345,'38012','Santa Blues','festival','festivales_wiki','Santa Blues es el nombre del festival internacional de blues que se celebra en Santa Cruz de Tenerife y que se ha consolidado entre los amantes del blues de Canarias. Está patrocinado por el Gobierno de Canarias, el Ayuntamiento de Santa Cruz de Tenerife y el Cabildo tinerfeño, y cuenta con la organización y…',NULL,NULL,'https://es.wikipedia.org/wiki/Santa_Blues');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184346,'50297','Saraqusta Film Festival','festival','festivales_wiki','El Saraqusta Film Festival (SFF) es un festival cinematográfico y televisivo que viene siendo organizado anualmente por el Ayuntamiento de Zaragoza desde 2021 y que está especializado en películas históricas. Su nombre procede de la denominación durante la dominación árabe de la ciudad de Zaragoza. Es conocido…',NULL,NULL,'https://es.wikipedia.org/wiki/Saraqusta_Film_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184347,'90551','Saraqusta Film Festival de 2021','festival','festivales_wiki','El Saraqusta Film Festival de 2021 se celebró en Zaragoza entre el 26 de septiembre y el 2 de octubre de 2021. Fue organizado por el Ayuntamiento de Zaragoza y la empresa Cosmos Fan, siendo sus sedes principales el Museo del Teatro de Caesaraugusta, los Cines Palafox y el Cine Cervantes. Contó con la colaboración…',NULL,NULL,'https://es.wikipedia.org/wiki/Saraqusta_Film_Festival_de_2021');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184348,'90551','Saraqusta Film Festival de 2022','festival','festivales_wiki','El Saraqusta Film Festival de 2022 se celebró en Zaragoza entre el 24 y el 30 de abril de 2022. Fue organizado por el Ayuntamiento de Zaragoza y la empresa Cosmos Fan. Las sedes principales fueron otra vez el Museo del Teatro de Caesaraugusta, los Cines Palafox y el Cine Cervantes.',NULL,NULL,'https://es.wikipedia.org/wiki/Saraqusta_Film_Festival_de_2022');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184349,'90551','Saraqusta Film Festival de 2023','festival','festivales_wiki','El Saraqusta Film Festival de 2023 se celebró en Zaragoza entre el 29 de abril y el 5 de mayo de 2023. Fue organizado por el Ayuntamiento de Zaragoza y la empresa Cosmos Fan. Las sedes principales fueron una vez más el Museo del Teatro de Caesaraugusta, los Cines Palafox y el Cine Cervantes.',NULL,NULL,'https://es.wikipedia.org/wiki/Saraqusta_Film_Festival_de_2023');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184350,'50297','Saraqusta Film Festival de 2024','festival','festivales_wiki','El Saraqusta Film Festival de 2024 se celebró en Zaragoza entre el 26 de abril y el 3 de mayo de 2024. Fue organizado por el Ayuntamiento de Zaragoza y la empresa Cosmos Fan, y el director fue un año más José Ángel Delgado. Las sedes principales fueron el Museo del Teatro de Caesaraugusta y el salón de actos de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Saraqusta_Film_Festival_de_2024');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184351,'90551','Saraqusta Film Festival de 2025','festival','festivales_wiki','El Saraqusta Film Festival de 2025 se celebró en Zaragoza entre el 25 de abril y el 2 de mayo de 2025. Fue organizado por el Ayuntamiento de Zaragoza y la empresa Cosmos Fan, y el director fue una vez más José Ángel Delgado. Las sedes principales fueron el Museo del Teatro de Caesaraugusta, el salón de actos de la…',NULL,NULL,'https://es.wikipedia.org/wiki/Saraqusta_Film_Festival_de_2025');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184352,'29051','Semana Internacional de Cine Fantástico y de Terror de Estepona','festival','festivales_wiki','La Semana Internacional de Cine Fantástico y de Terror de Estepona es una muestra de cine celebrada anualmente desde 1999 en la localidad malagueña de Estepona (España), dedicado, como su nombre indica, al cine fantástico y de terror.',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Internacional_de_Cine_Fantástico_y_de_Terror_de_Estepona');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184353,'18087','Semana Internacional de Órgano de Granada','festival','festivales_wiki','La Semana Internacional de Órgano de Granada fue un festival de música dedicado al órgano, que se celebra cada año durante la primera semana de noviembre desde 1989 en la ciudad de Granada, España. Estaba presidido por la organista Inmaculada Ferro. En la actualidad, y desde hace más de quince años, este ciclo fue…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Internacional_de_Órgano_de_Granada');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184354,'33024','Semana Negra de Gijón','festival','festivales_wiki','La Semana Negra de Gijón es uno de los ciclos de semana negra en España dedicado a la novela negra. Se creó en 1987 por iniciativa del editor Silverio Cañada, del escritor Juan Cueto y del diseñador Jesús Quirós, y organizada por el también escritor Paco Abril, y desde entonces se celebra en Gijón, Principado de…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_Negra_de_Gijón');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184355,'20069','Semana de Cine Fantástico y de Terror de San Sebastián','festival','festivales_wiki','La Semana de Cine Fantástico y de Terror de San Sebastián (País Vasco, España) comenzó su andadura en 1990, organizada por el Ayuntamiento de San Sebastián a través de la entidad pública empresarial Donostia Kultura.​',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_de_Cine_Fantástico_y_de_Terror_de_San_Sebastián');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184356,'47085','Semana de Cine de Medina del Campo','festival','festivales_wiki','La Semana de Cine de Medina del Campo es un festival cinematográfico que se desarrolla en la ciudad de Medina del Campo, Valladolid, comunidad autónoma de Castilla y León, España, desde 1988.​',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_de_Cine_de_Medina_del_Campo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184357,'25001','Semana de Música Antigua de Estella','festival','festivales_wiki','La Semana de Música Antigua de Estella (SMADE) es un evento anual organizado conjuntamente por la Dirección General de Cultura del Gobierno de Navarra y la Fundación Baluarte, que ofrece, cada año, una muestra de la mejor música antigua europea medieval, renacentista y barroca, producida en el ámbito local,…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_de_Música_Antigua_de_Estella');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184358,'28079','Semana del Cine Experimental de Madrid','festival','festivales_wiki','La Semana de Cine Experimental de Madrid es un festival que se realiza desde 1991 en Madrid. Tiene como objetivo el fomento de la investigación cinematográfica y servir de plataforma para que aquellos que se dedican al género experimental puedan mostrar anualmente sus trabajos. Tiene lugar todos los años en el mes…',NULL,NULL,'https://es.wikipedia.org/wiki/Semana_del_Cine_Experimental_de_Madrid');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184359,'08003','Serielizados Fest','festival','festivales_wiki','Serielizados Fest es el Festival Internacional de Series de Barcelona.',NULL,NULL,'https://es.wikipedia.org/wiki/Serielizados_Fest');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184360,'11027','Shorty Week International Film Festival','festival','festivales_wiki','Shorty Week International Film Festival (Festival Internacional de Cortometrajes Shorty Week) es un Festival Internacional de Cortometrajes que se celebra cada año actualmente en Cádiz, aunque sus primeras tres ediciones tuvieron lugar en la ciudad de El Puerto de Santa María, y que proyecta durante los días de su…',NULL,NULL,'https://es.wikipedia.org/wiki/Shorty_Week_International_Film_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184361,'08008','Sis Hores de Cançó','festival','festivales_wiki','Las Sis Hores de Cançó (Seis Horas de Canción) de Canet de Mar fue un multitudinario festival de nueva canción catalana del que se celebraron ocho ediciones anuales: desde 1971 hasta 1978. El origen del festival cabe hallarlo en la iniciativa del grupo scout de Canet de Mar, que empezó a organizar recitales como…',NULL,NULL,'https://es.wikipedia.org/wiki/Sis_Hores_de_Cançó');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184362,'03007','Skyline Film Festival','festival','festivales_wiki','El Skyline Benidorm Film Festival es, desde 2022, un festival calificador de los Premios Goya. Empezó como una muestra cinematográfica celebrada en la ciudad de Benidorm, España, que ha ido evolucionando desde su creación en 2017. En apenas nueve ediciones, el Skyline se ha consolidado como uno de los eventos clave…',38.53416667,-0.13138889,'https://es.wikipedia.org/wiki/Skyline_Film_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184363,'10037','SonoraCC','festival','festivales_wiki','El SonoraCC es un festival de música pop, rock e indie que se celebra en la ciudad de Cáceres el último fin de semana de junio. El festival se centra en bandas nacionales.',NULL,NULL,'https://es.wikipedia.org/wiki/SonoraCC');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184364,'21042','South Pop Festival','festival','festivales_wiki','El South Pop Festival fue un festival de música pop celebrado en sus últimas ediciones en la localidad costera de Isla Cristina (Huelva, España), y anteriormente en Sevilla. El festival es un ciclo de conciertos de grupos alternativos aunque algunos de ellos bien conocidos, en un ambiente relajado.​ Se celebra en…',NULL,NULL,'https://es.wikipedia.org/wiki/South_Pop_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184365,'29069','Starlite Festival','festival','festivales_wiki','El festival Starlite Occident pertenece al Grupo Starlite, junto a las empresas Starlite Universe, Fundación Starlite y Starlite Films. Es un evento musical que se celebra cada verano, desde el año 2012, en la Cantera de Nagüeles, un anfiteatro de roca al aire libre rodeado de vegetación, ubicado en la ciudad…',NULL,NULL,'https://es.wikipedia.org/wiki/Starlite_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184366,'28079','Suma Flamenca','festival','festivales_wiki','Suma Flamenca es un festival musical de flamenco que tiene lugar cada año en torno a junio en distintos puntos de la Comunidad de Madrid (España).',NULL,NULL,'https://es.wikipedia.org/wiki/Suma_Flamenca');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184367,'08003','Summercase','festival','festivales_wiki','Summercase fue un festival de música independiente creado en 2006 por la promotora musical Sinnamon. El evento tenía lugar simultáneamente en Barcelona y en Madrid durante un sábado y un domingo intercambiado ambas ciudades el mismo cartel, aunque con algunas variaciones. En Barcelona se celebraba en el Parc del…',NULL,NULL,'https://es.wikipedia.org/wiki/Summercase');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184368,'08003','Sónar (festival)','festival','festivales_wiki','El Festival Internacional de Música, Creatividad y Tecnología Sónar, más conocido como Sónar,​ es un festival de música electrónica y experimental​ de ámbito internacional celebrado en Barcelona.​ Fundado por Ricard Robles, Enric Palau y Sergi Caballero en 1994​ con posterioridad comenzó a celebrar ediciones…',NULL,NULL,'https://es.wikipedia.org/wiki/Sónar_(festival)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184369,'39075','Tanned Tin','festival','festivales_wiki','Tanned Tin es un festival de música celebrado durante noviembre inicialmente en Santander (España), aunque se trasladó a la ciudad de Castellón.',NULL,NULL,'https://es.wikipedia.org/wiki/Tanned_Tin');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184370,'43148','Tarraco Viva','festival','festivales_wiki','Festival anual sobre el mundo romano celebrado en el mes de mayo en la ciudad de Tarragona, de la que coge su antiguo nombre romano, Tarraco. El festival tiene como objetivo principal la divulgación del conocimiento de la Edad Antigua en época romana. En el festival, participan numerosos grupos de reconstrucción…',NULL,NULL,'https://es.wikipedia.org/wiki/Tarraco_Viva');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184371,'29067','Teatro Cervantes (Málaga)','festival','festivales_wiki','El Teatro Cervantes de la ciudad española de Málaga es uno de los espacios escénicos más antiguos de la capital de la Costa del Sol. Data de 1870 y cuenta con mil ciento treinta y cuatro localidades. Es la sede principal de la Orquesta Filarmónica de Málaga y del Festival de Málaga.',36.72475348,-4.41855252,'https://es.wikipedia.org/wiki/Teatro_Cervantes_(Málaga)');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184372,'29067','Teatro Echegaray','festival','festivales_wiki','El teatro Echegaray es un espacio escénico situado en el número 6 de la calle Echegaray del centro histórico de la ciudad de Málaga, España. Es propiedad del Ayuntamiento de Málaga y está gestionado por el teatro Cervantes.',36.721425,-4.41935278,'https://es.wikipedia.org/wiki/Teatro_Echegaray');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184373,'29067','Teatro del Soho','festival','festivales_wiki','El teatro del Soho, ubicado en el antiguo teatro Alameda (1961-2018), es un teatro privado de la ciudad de Málaga, España. Está situado en la calle Córdoba, en el barrio del Ensanche Heredia, en el distrito Centro. Su propietario es el actor malagueño Antonio Banderas.',36.7161667,-4.4218889,'https://es.wikipedia.org/wiki/Teatro_del_Soho');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184374,'19130','Tenorio Mendocino','festival','festivales_wiki','El Tenorio Mendocino es una representación de la obra Don Juan Tenorio de José Zorrilla que se celebra anualmente el fin de semana más próximo al 31 de octubre en las calles y en los principales monumentos de la ciudad de Guadalajara (España).​​ Está declarada como Fiesta de Interés Turístico Regional por la Junta…',NULL,NULL,'https://es.wikipedia.org/wiki/Tenorio_Mendocino');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184375,'41091','Territorios Sevilla','festival','festivales_wiki','Territorios Sevilla fue un festival de música que tenía lugar en la capital hispalense cada primavera, organizado por una empresa privada y con apoyo institucional y de patrocinadores privados. En su primera edición en 1998 y en las tres siguientes, la programación mantenía en todas las actuaciones algún elemento…',NULL,NULL,'https://es.wikipedia.org/wiki/Territorios_Sevilla');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184376,'08123','TerrorMolins','festival','festivales_wiki','El Festival de Cine de Terror de Molins de Rei o TerrorMolins es un festival de cine especializado en producciones de terror, que se celebra anualmente en la localidad de Molins de Rey, Cataluña, España.',NULL,NULL,'https://es.wikipedia.org/wiki/TerrorMolins');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184377,'09001','Tintorrock','festival','festivales_wiki','El Festival Tintorrock es un festival de música Punk Rock que nació el año 1998 en Aranda de Duero y que ha ido trasladando su lugar de celebración por varios lugares de la provincia de Burgos, realizándose alguna edición incluso en Salamanca y Navarra. Su principal organizador es el sello discográfico Tintorrock…',NULL,NULL,'https://es.wikipedia.org/wiki/Tintorrock');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184378,'30016','Trovalia','festival','festivales_wiki','Trovalia es un festival internacional de poesía improvisada y cantada que se celebra en el municipio español de Cartagena durante los primeros días de agosto. Está organizado por la asociación de troveros del Campo de Cartagena "José María Marín" y cuenta con el patrocinio del Ayuntamiento de Cartagena.',NULL,NULL,'https://es.wikipedia.org/wiki/Trovalia');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184379,'03904','Universimad','festival','festivales_wiki','Universimad es una propuesta desarrollada paralelamente a Festimad que cuenta con 4 ediciones hasta la fecha (2004-2007), y que se celebra el 15 de mayo, día de San Isidro, lo que ha implicado que también reciba el nombre de Universimad San Isidro.​',NULL,NULL,'https://es.wikipedia.org/wiki/Universimad');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184380,'46250','Valencia Negra','festival','festivales_wiki','El Festival de Género Negro de Valencia, conocido como Valencia Negra o VLC Negra, es un festival literario que se celebra los primeros días del mes de mayo del año promovido desde 2013 por los escritores Jordi Llobregat, Bernardo Carrión,​ Marina López Martínez (Marina Lomar) y Santiago Álvarez.​ El festival se…',NULL,NULL,'https://es.wikipedia.org/wiki/Valencia_Negra');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184381,'47186','Valladolid Latino','festival','festivales_wiki','El Valladolid Latino fue un festival de música que se realizó en la ciudad de Valladolid entre los años 2006 y 2015. Estuvo consolidado entre los festivales de su tipo a nivel tanto nacional como internacional.​ Fue suspendido en 2007 debido a las lluvias.​ En 2016 se optó por cancelar el festival por considerarlo…',NULL,NULL,'https://es.wikipedia.org/wiki/Valladolid_Latino');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184382,'02027','Villa-Rock-Bledo','festival','festivales_wiki','El festival Villa-Rock-Bledo fue un festival musical organizado en la ciudad de Villarrobledo (Albacete), que se celebró el fin de semana previo al 1 de mayo de 2007. Trató de recuperar la esencia que, en sus orígenes, tuvo el festival Viña Rock y, desde sus inicios en 1996, se vino celebrando en esta localidad…',NULL,NULL,'https://es.wikipedia.org/wiki/Villa-Rock-Bledo');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184383,'22250','Villanoir','festival','festivales_wiki','Villanoir, o el Encuentro Pirenaico de Género Negro de Villanúa, son unas jornadas de literatura negra y de misterio, enmarcadas dentro de las Semanas Negras de España, convocado en el municipio de Villanúa durante la primera semana del mes de marzo de la convocatoria correspondiente.​',NULL,NULL,'https://es.wikipedia.org/wiki/Villanoir');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184384,'48034','Vértigo Rock Festival','festival','festivales_wiki','Vértigo Rock Festival El festival Vértigo Rock surge de las inquietudes de varios músicos locales amantes de la cultura en forma de música para conseguir relaciones más estrechas entre bandas locales y bandas nacionales. Tiene su primera edición en Ermua en octubre de 2007, fecha que se trasladó en los años…',NULL,NULL,'https://es.wikipedia.org/wiki/Vértigo_Rock_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184385,'06018','Vía de la Plata Festival','festival','festivales_wiki','El festival Vía de la Plata ha sido creado en el año 2008 en la ciudad española de Mérida, por la promotora musical ''A Vallekas Producciones''. Se celebra en las instalaciones del albergue Juvenil ''El Prado'', con una capacidad para 30000 espectadores y el género musical predominante es el metal. En su primera…',NULL,NULL,'https://es.wikipedia.org/wiki/Vía_de_la_Plata_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184386,'10037','WOMAD','festival','festivales_wiki','WOMAD (siglas de World Of Music, Arts & Dance) es un festival cultural organizado por la organización mundial WOMAD en el que se incluyen música popular, música étnica, artesanía y otras actividades lúdicas. En España, se celebra en la ciudad de Cáceres desde el año 1992. También se celebró en Las Palmas, desde…',NULL,NULL,'https://es.wikipedia.org/wiki/WOMAD');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184387,'46105','Zevra Festival','festival','festivales_wiki','Zevra Festival es un festival de música que se celebra en la localidad de Cullera (Comunidad Valenciana, España) desde el año 2022. Se lleva a cabo durante el verano y presenta una variedad de géneros musicales.',NULL,NULL,'https://es.wikipedia.org/wiki/Zevra_Festival');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184388,'48020','Zinebi','festival','festivales_wiki','El Festival Internacional de Cine Documental y Cortometraje de Bilbao - ZINEBI es un festival de cine internacional que se celebra anualmente en Bilbao desde 1959. Premia cortometrajes de ficción, documentales y animación.​ Desde 1974, es el único festival internacional de España reconocido por la FIAPF en la…',43.2595177,-2.9247434,'https://es.wikipedia.org/wiki/Zinebi');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184389,'48020','Zinegoak','festival','festivales_wiki','Zinegoak es el festival internacional de cine LGBTIQ+ que se celebra anualmente en Bilbao, País Vasco. En el festival se proyectan largometrajes de ficción, largometrajes documentales, cortometrajes de ficción, cortometrajes documentales y obras experimentales, entre otras propuestas escénicas junto con gran…',NULL,NULL,'https://es.wikipedia.org/wiki/Zinegoak');
INSERT OR IGNORE INTO entidades(id,codigo_ine,nombre,tipo,fuente,descripcion,latitud,longitud,wiki_url) VALUES(184390,'47186','Zorrilla''s Fest','festival','festivales_wiki','Zorrilla''s Fest es un festival cultural LGBTI+ anual iniciado en 2022 en la ciudad española de Valladolid, organizado por Fundación Triángulo Castilla y León y patrocinado por el Ayuntamiento de Valladolid. Es un evento que se enmarca dentro del mes del Orgullo. Durante el festival se realizan actividades como…',NULL,NULL,'https://es.wikipedia.org/wiki/Zorrilla''s_Fest');

